quests[25813] = { id = 25813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", sourceObjective = "Slay Whrrrl.", completion = "Well then, let's see them get any kind of magical hocus pocus air support now when we take over!", sourceObjectiveStatus = "unverified-source-field" }
quests[25814] = { id = 25814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", sourceObjective = "Slay Whrrrl.", completion = "Well then, let's see them get any kind of magical hocus pocus air support now when we take over!", sourceObjectiveStatus = "unverified-source-field" }
quests[25815] = { id = 25815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked by red dragons.  Dragons controlled by orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Bring me my mead, {class}. It's down in the cellar of the inn. As far away as I put it from me, I can't go without it in the end.", sourceObjective = "Obtain Fitzsimmons' Mead from the cellar of the inn in Menethil Harbor.", progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!", sourceObjectiveStatus = "unverified-source-field" }
quests[25816] = { id = 25816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed to Roam", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north. On one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nI'm haunted by them day and night. First Mate Snellig calls for me! He's supposed to be dead! Please, {name}, look for him near the shipwrecks and just...tell him to leave me alone!", sourceObjective = "Talk to the ghost of First Mate Snellig.", completion = "Fitzsimmons sent you, didn't he? It's been so long...", sourceObjectiveStatus = "unverified-source-field" }
quests[25817] = { id = 25817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Crew", description = "The sailors of the Third Fleet are damned, forever cursed to wander these shores in agony. Fitzsimmons' anguish is tied to us; so long as we suffer, there can be no rest for him, either.\n\nYou must end the suffering of my crewmates' spirits. Purge their ghosts from this plane, and return to me.", sourceObjective = "Kill 5 Cursed Sailors and 5 Cursed Marines in The Lost Fleet.", completion = "The cries of anguish have been stifled...but the source of the curse still lurks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25818] = { id = 25818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Curse", description = "To break the curse, there must be a reckoning. Captain Halyndor damned us all to covet a forbidden artifact; the Eye of Paleth. His spirit still covets it, standing guard over the strongbox of his old ship, the Intrepid.\n\nVanquish the soul of the one who cursed us so, {class}. Defeat the Captain, claim his key, and spirit the Eye of Paleth far from this place.", sourceObjective = "Get the Intrepid Strongbox Key from Captain Halyndor.", progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly.", sourceObjectiveStatus = "unverified-source-field" }
quests[25819] = { id = 25819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light. This must be the foul Eye of Paleth that damned these sailors' souls.\n\nSuch corruption should be purged. Perhaps a priest in Menethil Harbor could help you.", sourceObjective = "Bring the Cursed Eye of Paleth to Glorin Steelbrow at Menethil Harbor in Wetlands.", progress = "How can I help you, lad?", completion = "The Eye of Paleth? You say Fitzsimmons sent you out?\n\nBy the light...not again. Fitzsimmons is dead, lad. You've not the first to come to me like this, either.", sourceObjectiveStatus = "unverified-source-field" }
quests[25820] = { id = 25820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mother's Worries", description = "My son Gimlok's the light of my life. It warms my heart to see him playin' with the other children.\n\nI can't help but worry, though. There's sharks not but a few feet away in the bay. If it's deep enough for one to swim its way here...\n\nI can't bear it! Please, you're clearly one {race} that's seen tougher situations than us townsfolk. Would you get rid of those nasty sharks for me? At least a few?", sourceObjective = "Kill 10 Harbor Shredfins.", completion = "Oh, bless your heart, to do such a thing for a married woman like me. You're too kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25821] = { id = 25821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Kind of Job", description = "You've done an admirable job down here, {name}. Force Commander Valen has taken notice and requested that you see him immediately. He's got a special mission lined up for you - one that'll hopefully put a cold stop on the Horde's incursion into Stonetalon.", sourceObjective = "Report to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "I knew that you'd be a special snowflake when I first set my eyes upon you, {name}. So special, in fact, that I'd trust no one else here with what I'm about to ask of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25822] = { id = 25822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armaments for War", description = "I am going to need to put you in harm's way once more, {name}. To the east you will find a mineral rich excavation site that was recently overrun by the Horde. At that site are crates of our weaponry, scattered about all over the place. The Horde has only recently taken over, so it is unlikely that they've found all of our supplies.\n\nGet in there and get our Grimtotem friends some weapons!", sourceObjective = "Collect 10 Alliance Weapon Crates.", progress = "Have you gathered the armaments of war?", completion = "This should be enough to supply a hundred Grimtotem! Now to present the weaponry to their chieftain.", sourceObjectiveStatus = "unverified-source-field" }
quests[25823] = { id = 25823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unrelenting Horde", description = "While it is of utmost importance that you secure weapon crates immediately, we need the Unearthed Grounds to the east clear of Horde. If we are to open a supply line for our Grimtotem allies, we're going to need full access to the dig site.\n\nKill all Horde that you come across at the Unearthed Grounds, {name}. For the glory of the Alliance!", sourceObjective = "Slay 12 Horde enemies at the Unearthed Grounds.", completion = "I will call for the infantry to move in and clear up whatever might be left over. If only we had ten-thousand more like you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25824] = { id = 25824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debriefing", description = "This soldier was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", sourceObjective = "Speak to Private Pollard and learn about his ordeal.", progress = "That's it, {race}.\n\nThat's all I know...", completion = "Well, it's not encouraging, but it's something...", sourceObjectiveStatus = "unverified-source-field" }
quests[25825] = { id = 25825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Fizzle on the Speedbarge, and let him know the good news!", sourceObjective = "Deliver the Barrel of Oil to Fizzle Brassbolts on Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "What's this? Is that oil?!", completion = "It is oil! You're really proving yourself to be invaluable, {name}!\n\nToo bad I'm going to have to send you off now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25826] = { id = 25826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Pozzik on the Speedbarge, and let him know the good news!", sourceObjective = "Deliver the Barrel of Oil to Pozzik on Fizzle & Pozzik's Speedbarge in Thousand Needles.", progress = "Hello again, friend. Is that oil?!", completion = "It is oil! You're the best, {name}!\n\nToo bad I'm going to have to send you off now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25830] = { id = 25830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Living Lorekeeper", description = "You have awakened the ancients, {name}, but the wilderness spirit Aessina remains silent. With her help, we can turn the tide of this attack and undo the damage Twilight's Hammer has done.\n\nThere may be one who can help us. The oldest of the trees, Nordu, stood in the center of what is now the Flamewake for thousands of years. His wisdom is as old as this mountain. If that old tree still lives, perhaps he can awaken Aessina... seek him out.", sourceObjective = "Seek out Nordu, an Ancient of Lore, at the Flamewake in Mount Hyjal.", completion = "I ... have not yet ... perished.", sourceObjectiveStatus = "unverified-source-field" }
quests[25832] = { id = 25832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Aviana", description = "{name}, you've done all you can here. This whole cavern is about to collapse in on itself!\n\nI'll gather up the last of our feathered steeds and ensure that the flamegate is sealed behind me.\n\nYou should go on ahead and let Aviana know that this abominable hatchery is no more!", sourceObjective = "Return to Aviana at the Shrine of Aviana in Mount Hyjal.", completion = "<Aviana's face is immobile as you tell her about what happened within the hatchery.>\n\nThey stole my eggs, {class}. They took them to that foul place. Corrupted them.\n\nMy children stolen, tormented, killed in a vat of flame... Yes, we will make Twilight's Hammer pay.\n\nBut I confess, part of me wants to fly up and simply watch this whole... world... burn.", sourceObjectiveStatus = "unverified-source-field" }
quests[25834] = { id = 25834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death by Proxy", description = "Can you hear them fighting down below, {name}? It would appear that the Grimtotem tauren are no longer in the good graces of the Horde. I don't know what happened, but we can turn this to our advantage.\n\nI will arrange a meeting with an ambassador from the Grimtotem. What I need you to do is put together a peaceful offering.\n\n<Force Commander Valen points to Cookie.>\n\nTalk to \"Cookie,\" {name}. He's already been briefed on what we need to do.", sourceObjective = "Speak with \"Cookie\" McWeaksauce at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "The name be \"Cookie,\" lad: greatest cook 'cross Azeroth. Now the Commander's told me what we be needin' to do. To gain audience with the Grimtotem chief we're gonna have to cook up the finest of tauren cuisine.\n\nYe get me the ingredients and I'll put together an offerin' no tauren could refuse. Not even a grim tauren or whatever them things be.", sourceObjectiveStatus = "unverified-source-field" }
quests[25835] = { id = 25835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Freewind Post", description = "Alas, it's time for you to leave. How quickly the chicks fall from the nest. Or, something.\n\nAnyway, you've done solid work here, my friend, but Quentin and the night elves have been crying that they urgently need your help with the Grimtotem at Freewind Post to the northwest.\n\nIf you ask me, it's a lost cause, but who knows... maybe with your help they'll actually succeed?", sourceObjective = "Speak with Quentin at Freewind Post in Thousand Needles.", completion = "I'm glad that Fizzle finally sent you here. We're helping the tauren to retake Freewind Post and push back the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[25836] = { id = 25836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Freewind Post", description = "Well, it looks like it's time for us to part ways, at least for a while. To the northwest, the tauren of Freewind Post are in desperate need of your assistance in pushing back the Grimtotem clan!\n\nYou know, you've been such a great help around here, I bet you're going to be their <hero/heroine> in no-time!", sourceObjective = "Speak with Thalia Amberhide at Freewind Post in Thousand Needles.", completion = "I am honored that you have come to help, {class}. It was kind of Pozzik to send you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25837] = { id = 25837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Peace Offerin'", description = "To make the perfect peace offerin', I be needing the following ingredients:\n\nKalimdor eagle eggs, obtained from Kalimdor eagle nests. They be scattered about the forest to the west.\n\nRam haunches! You'll find ram haunches on Stonetalon rams.\n\nThe last ingredient be a little tougher to come by, but we be needin' it to make the ramlette. Head southwest to Boulderslide Canyon and find the kobold caves. Kill the kobolds and take their special cheese.\n\nBring it all back and I'll cook up a masterpiece!", sourceObjective = "Collect 6 Kalimdor Eagle Eggs, 8 Ram Haunches and 10 Boulderslide Cheese pieces.", progress = "This ramlette ain't gonna make itself!", completion = "Stand back, {name}, there's about to be a flavor explosion and I wouldn't want ya gettin' hurt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25838] = { id = 25838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help from Steelgrill's Depot", description = "With your help, we've managed to push toward Frostmane Retreat. Our forces will soon be in position to dwindle down the Frostmane trolls' reserves, leaving their village open to attack.\n\nThat's where the Gnomeregan covert ops team comes in. Their technicians have figured out a way to deploy operatives behind enemy lines without alerting the Frostmanes to our presence. Head to Steelgrill's Depot, just northeast of town, and speak with Delber Cranktoggle. He'll tell you more about it.", sourceObjective = "Speak to Delber Cranktoggle at Steelgrill's Depot.", completion = "Ah, you must be the {race} that Captain Tharran said he'd be sending. I've already used the deploy-a-tron to get most of the covert ops team into position at Frostmane Retreat. They're just waiting on your arrival.", sourceObjectiveStatus = "unverified-source-field" }
quests[25839] = { id = 25839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultrasafe Personnel Launcher", description = "The cataclysm has brought our enemies closer to home, so the chief of Gnomeregan covert operations asked me to build a device to dispatch personnel quickly and quietly to any corner of Dun Morogh.\n\nBehold, the ultrasafe personnel launcher!\n\nWith a jolt of electricity and the benefit of a VLD parachute system, uh, that's 'very late deployment' for you laymen, this baby'll get you to the front in no time. Just hop aboard and prepare for flight! Slamp Wobblecog will be waiting for you in the drop zone.", sourceObjective = "Use the Ultrasafe Personnel Launcher to deploy to Frostmane Retreat.", progress = "Did you survive the deployment?", completion = "Don't worry, the feeling of being zapped won't stay with you for more than a few minutes. All in all, it's not a bad way to get where you're going. That parachute system needs some work, though. Very late deployment, indeed. Sometimes, too late. Anyway, we have a mission to carry out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25840] = { id = 25840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Resistance", description = "The Frostmane chieftain died in the initial trogg onslaught, but they've been led by a well-respected warrior ever since. Battok the Berserker was the one who organized the Frostmane retreat, the construction of the new village, and the strikes against Kharanos and the mountaineers.\n\nIf we remove Battok, the Frostmanes' organization should crumble, leaving the mountaineers free to pick off the survivors. Battok will be in the village, just east of here.", sourceObjective = "Slay Battok the Berserker and 5 Frostmane Warriors in Frostmane Retreat.", completion = "Excellent job, {name}. With Battok dead, I'll send the signal to Captain Tharran. This should be the end of the Frostmane threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25841] = { id = 25841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike From Above", description = "Delber's technicians have been up day and night helping us prepare for this strike. Aside from building and tuning the personnel launcher, his men have prepared the covert operations air wing for a strike on Frostmane Retreat. They'll be waiting for a signal to begin their strikes.\n\nTake this flare with you, and set it off near the cluster of buildings at the northern end of the village, and the buildings at the southern end of the village. The flying machines will make a quick strike at each site.", sourceObjective = "Use the Signal Flare to call in airstrikes at the northern and southern ends of Frostmane Retreat.", progress = "Did you signal the air wing to take out the troll buildings?", completion = "Both you and the air wing performed admirably. There's no way that the Frostmanes will remain here now. All that remains is to begin mopping up the survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[25842] = { id = 25842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firefight", description = "It is... too late for me. Burned to all but the core. I have lived eons ... yet still my end seems sudden.\n\nNew life can spring from old. I still have wisdom to pass on. Please... do not let them take me before my work is done.\n\nKeep the tormentors at bay... just a little longer, {class}.\n\nGive me minutes, and I will give you a thousand lifetimes.", sourceObjective = "Kill 5 Fiery Tormentors to keep them from Nordu.", progress = "Are you there, {class}? My vision is failing... I hear fighting...", completion = "Thank you, {race}.\n\nI am ready now.\n\nAll that I am, and all that this forest once was... it is now yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[25843] = { id = 25843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla's Revenge", description = "The mountain blooms again! If we act quickly, we can press our advantage.\n\nOur old friend Tortolla, the turtle ancient, is already on the move. At his own pace, of course...\n\nFind Tortolla east of here, at the head of the path leading down into the scorched plains. Our strongholds there fell early in the campaign, but perhaps now we can reclaim them.", sourceObjective = "Speak to Tortolla at the Scorched Plain in Mount Hyjal.", completion = "{race}.\n\nI remember you. Savior of my children.\n\nThe time has come. For vengeance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25844] = { id = 25844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sating the Savage Beast", description = "You heard the commander, {name}. Deliver me perfect offerin' to the Grimtotem ambassador! Him and his crew be waitin' for you at the bottom of the southeastern path.\n\nThis is sure to put us in the good graces of their chieftain!", sourceObjective = "Deliver the Meaty Offering to Ton Windbow at Grimtotem Post in Stonetalon Mountains.", progress = "<Ton Window sniffs at the air and raises his left hand.>\n\nYou have brought something for us?", completion = "<Ton and his bodyguards scarf down the meaty offering.>\n\nThis... this is the greatest thing I have ever tasted. You may prove to be a valuable ally, but before the Grimtotem agree to work with the Alliance, you must agree to our terms. I will now give to you those terms as told to me by my leader. Take them back to your commander and see if he accepts.", sourceObjectiveStatus = "unverified-source-field" }
quests[25845] = { id = 25845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terms of Service", description = "Grimtotem need weapons! The Horde, empowered by their Warchief and with the help of their new goblin allies, have amassed powerful weaponry. Our armaments are simply no match for their firepower. Supply the Grimtotem with strong weapons and we will work together to destroy the Horde!\n\nThese are our demands! Supply the Grimtotem and we will fight for the Alliance!", sourceObjective = "Deliver the Grimtotem Terms of Service to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", progress = "Well???", completion = "Weapons, eh?\n\n<Force Commander Valen sighs.>\n\nI'm about to make an executive decision here, {name}. Let's hope this pays off, else King Wrynn will have my head!", sourceObjectiveStatus = "unverified-source-field" }
quests[25846] = { id = 25846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundig Darkcloud, Chieftain of the Grimtotem", description = "The Grimtotem chieftain awaits your arrival, {name}. Take the weapon crates with you and head to Grimtotem Post, south of here.\n\nGood luck, {name}. Should anything happen to you I will personally notify your next of kin and let King Wrynn know what you have done for the Alliance.", sourceObjective = "Deliver the Alliance Weapon Crates to Grundig Darkcloud at Grimtotem Post in Stonetalon Mountains.", progress = "Do you have the weapons?", completion = "These are fine weapons! Powerful steel! My warriors will be unstoppable armed with such weaponry. Magatha smiles down upon you, {name}.\n\nThere is but one thing I ask of you, perhaps two.", sourceObjectiveStatus = "unverified-source-field" }
quests[25847] = { id = 25847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Supremacy", description = "Throughout all of Greatwood Vale you will find Grimtotem under attack by the Horde. Hellscream's armies show no mercy and no compassion, killing anything that stands in their way.\n\nBut no more! Take the armaments you brought for us and find Grimtotem in battle with the Horde. Give them the weapons of the Alliance and watch as they destroy their Horde assailants! Go, there is much work to do, ally.", sourceObjective = "Use the Alliance Weapon Crate to arm 12 Grimtotem.", progress = "Have you armed the Grimtotem?", completion = "The fight is far from over, {name}. The Horde generals still live...", sourceObjectiveStatus = "unverified-source-field" }
quests[25848] = { id = 25848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downfall", description = "By the time that we received word that Hellscream had sent another mag'har orc to oversee the Horde troops in southern Stonetalon, it was too late. Camp Aparaje was burned to the ground and all Grimtotem in the area incinerated.\n\nNow the Horde have four of their most fearsome generals commanding the battle for Greatwood Vale, including the mag'har, General Glubgok.\n\nYou must travel to the ruins of Camp Aparaje, south of here, and kill the generals. We stop the Horde NOW! Return to me with their mark!", sourceObjective = "Kill the Horde generals at Camp Aparaje and recover the Insignia of the Horde General.", progress = "Are the generals dead?", completion = "<Grundig crushes the insignia in his massive fist.>\n\nYes, ally, you have done it! It will take Hellscream weeks to recover from this blow. Southern Stonetalon belongs to the Grimtotem... and the Alliance, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[25849] = { id = 25849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Archaeology Attacks", description = "Listen, <lad/lass>, any good archaeologists know the risks that come with the job. If you don't unearth an ancient evil or get cursed by wicked spirits at least once in your career, you're not digging up anything worthwhile!\n\nNo, the real archaeologists know that a little thing like fossilized bones reanimating into skeletal creatures is no reason to stop working.\n\nI still need those fossil bones. Collect 'em from the fossil monsters roaming around and bring them back to me, and I'll reward you.", sourceObjective = "Collect 20 Fossilized Bones from Living Fossils.", progress = "Don't be coy about it, now! Bring back a good armful of 'em!", completion = "See? Not bad, eh? Why, I almost wish all my finds decided to dig themselves up for me. It'd make my job a lot easier!\n\nOf course, you made it easier too, {name}. Much obliged.", sourceObjectiveStatus = "unverified-source-field" }
quests[25850] = { id = 25850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strike the Earth!", description = "In case you didn't notice, the land here in the Wetlands is pretty messed up. Floods, earthquakes... and on top of it all, even the ground's got a wild hair now.\n\nI never thought we'd be attacked by our own dig site, but sure enough, big chunks of it are now rampaging around trying to flatten any dwarf they see.\n\nYou look like a strong, strapping young {race}... mind going down there and slapping some sense into the clods?", sourceObjective = "Kill 7 Paleolithic Elementals.", completion = "That's showin' em what for! Good on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25851] = { id = 25851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dances with Grimtotem", description = "Return now to your leader and tell him all that you have done for the Grimtotem. Tell him that the Alliance may pass freely across our borders.", sourceObjective = "Report to Force Commander Valen at Northwatch Expedition Base Camp in Stonetalon Mountains.", completion = "Outstanding work, {name}! Now our forces only need to worry about the Horde as they enter Stonetalon.", sourceObjectiveStatus = "unverified-source-field" }
quests[25852] = { id = 25852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All's Clear", description = "Pack up your gear, {name}, it's time to join up with the rest of the Northwatch forces in Southern Barrens. Your first mission in Southern Barrens should be fairly straightforward.\n\nTwo days ago we received a distress signal from Commander Walpole. He and his battalion are pinned down in Stonetalon Pass, just outside of Honor's Stand. They've got Horde all over the place! Get there and help him out. I'll forward news of our alliance with the Grimtotem to Northwatch command.", sourceObjective = "Report to Commander Thomas Walpole at Stonetalon Pass in Southern Barrens.", completion = "You say the Grimtotem are no longer a threat? That's great, but we've got Horde all up our keesters!", sourceObjectiveStatus = "unverified-source-field" }
quests[25853] = { id = 25853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tooling Around", description = "I'm in charge of supplying this dig. It's not that bad, but having to pick up and move out so fast wasn't exactly ideal!\n\nArchaeologists need tools, you know. You can't run around pulling up priceless antiquities with your bare hands. If you're going back to the dig site, can you bring back the tools that got left behind?", sourceObjective = "Collect 6 Archaeologist's Tools.", progress = "Are they all here? We left a lot back there.", completion = "That's a relief! Maybe we can dig our way out of the hole we're still in, eh?\n\nNo, nevermind, just a bad joke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25854] = { id = 25854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Call Him Bitey", description = "Have you heard some raptors are intelligent enough to be domesticated? It's true! I've seen hunters tame them.\n\nIt gets quite lonely out here, you know, even with Wenna to keep me company... a pet's just what I need to brighten my spirits. A little baby raptor would be the best!\n\nIf you're out there slaughtering the adults, would you mind bringing me back some mature eggs? You can tell if they're ready to hatch by the wobbling.", sourceObjective = "Collect 6 Wobbling Raptor Eggs.", progress = "Do you have enough eggs? I can't take my chances with only one. Statistics, you know.", completion = "Wonderful! These should be ready to hatch within the day...\n\nNow I just need to cobble up a raptor pen before they all hatch nigh-simultaneously. What could go wrong?", sourceObjectiveStatus = "unverified-source-field" }
quests[25855] = { id = 25855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizmos and Gadgets", description = "I've been coming up short on parts recently for my engineering projects, and the other day I finally saw why: the Mosshide gnolls have been making off with them!\n\nI don't have any idea what they could possibly want them for, but I need those gizmos back. They're probably strewn all over the marsh by now, but if you see any, could you gather them and bring them back?", sourceObjective = "Find 7 Swiftgear Gizmos.", progress = "Did you find them?", completion = "Oh, wonderful! I'll be able to start reassembling these right away. Thank you so much!", sourceObjectiveStatus = "unverified-source-field" }
quests[25856] = { id = 25856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Hides", description = "I've skinned crocs in the wetlands for years, {class}. Things have changed though.\n\nYou see, not to bore you with a sob story, but when the cataclysm flooded Menethil Harbor, our house went with it. My wife and kids don't have a place to stay, and I need to make as much money as I can to get us under a roof again.\n\nI've been skinning crocs 'til I was too tired to move, but I still need more skins to sell. If you bring me some croc hides, I'll pay you a bit for them.", sourceObjective = "Collect 10 Marshy Crocolisk Hides from Wetlands Crocolisks.", progress = "Got any croc hides for me?", completion = "I'm much obliged, {class}. This'll go a ways towards getting my family back on their feet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25857] = { id = 25857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Horrorjaw", description = "I've been tempted to go after the big kill... the largest crocolisk out there, Horrorjaw. His hide alone would be enough to get my family out of this hole.\n\nBut I'm no fool. One mistake and I could lose a leg, or my life, and then where would my wife and kids be? Still homeless and without a father to care for them.\n\nIt's not my proudest moment, but I'll pick my family's safety over pride any day. Please, {class}... hunt Horrorjaw for me. You'll find him in his shady pool to the north, lurking.", sourceObjective = "Slay Horrorjaw and collect Horrorjaw's Hide.", progress = "Did you get it? Do you have Horrorjaw's hide?", completion = "Amazing! You're a true hero, {name}. I'll never forget what you've done for me and my family.\n\nI know it's not much, but please, take this with my blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[25858] = { id = 25858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Her Lady's Word", description = "Lady Sira'kess has begun preparations for the ritual of summoning, but the Crucible of Nazsharin has been stolen from us. The Kvaldir have surely taken it with them as they retreated to shallower waters.\n\nSpeak to the caste leaders to secure a war party, and then lead them in retrieving the artifact from Biel'aran Ridge to the east.\n\nI trust you my Battlemaiden, for you have never failed in any task that I have given you. As I am revered to the Queen, so are you revered to me. Go with my blessings.", sourceObjective = "Speak to Fathom-Lord Zin'jatar, Lady Sira'kess, and Overseer Idra'kess.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Reinforcements have begun to circle the waters around the ledge, preparing for the attack. They await only your lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[25859] = { id = 25859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Trespass Forgiven", description = "I know that you, like our revered lady, have unfortunate streaks of mercy that you succumb to at times. I would advise against such kindnesses this day. The Kvaldir are proud, and they will strike back if we do not cripple them completely. Kill all that you find.\n\nSadly, I have the inglorious task of making sure none return to the city, so you can go have all of the fun. I will cheer you on though, of course.", sourceObjective = "Kill 20 Kvaldir on the Vrykul Ledge.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Not one slipped through to the bridge. Not one.\n\nIt was very boring. I'd appreciate it if you shared a little next time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25860] = { id = 25860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At All Costs", description = "We are to begin the ritual immediately, and you are to see to it that we are not interrupted.\n\nSlaughter any Kvaldir that enter the temple. See to it that my priestesses live to see their task complete, no matter the cost.", sourceObjective = "Kill 20 Kvaldir attackers within Quel'Dormir Temple.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "I am trusting you to safeguard us, Battlemaiden.", completion = "Azjentus is to be taken at his word. Lady Naz'jar's Honor Guard should be sufficient to see the rest of the ritual through.", sourceObjectiveStatus = "unverified-source-field" }
quests[25861] = { id = 25861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting An Example", description = "The High-Shaman are in the buildings nearby, chanting and taunting, but not daring to approach me. These Kvaldir find their courage and strength only in the mist. They are a pitiful nuisance beneath the waves.\n\nI came bearing a message. If your ladyship has the time, bring a high-shaman to my feet that I might deliver this message to him and his people.", sourceObjective = "Bring a Kvaldir High-Shaman to the feet of Executioner Varathress.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "If your ladyship has the time, bring a high-shaman to my feet that I might deliver a message to him and his people.", completion = "My scythe is sated. Thank you, my lady.", sourceObjectiveStatus = "unverified-source-field" }
quests[25862] = { id = 25862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Property", description = "Our revered lady has sent me to aid you in your task. She wants you to retrieve the stolen Crucible of Nazsharin and bring it back here as soon as you can.\n\nShe grows impatient to start the ritual of summoning so that we might fully begin our preparations for war.", sourceObjective = "Retrieve the Crucible of Nazsharin.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "The crucible looks far too heavy to carry on your own, but more than enough naga forces remain to prepare it for transport.", sourceObjectiveStatus = "unverified-source-field" }
quests[25863] = { id = 25863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chosen Burden", description = "With the Crucible of Nazsharin, all that remains is to inform Lady Naz'jar of your success.", sourceObjective = "Return to the western edge of the Biel'aran Ridge with news of the Crucible of Nazsharin.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", completion = "Well done, my Battlemaiden.\n\nThis crucible will serve as a font of power for our summoning ritual. With it, Sira'kess will beckon our allies from the depths to bolster our already swelling forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[25864] = { id = 25864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinosaur Crisis", description = "We've been getting more and more reports of raptor attacks in the area. I'm seeing to it that this place is safe enough for more settlement to start occuring, so I've put a bounty on the buggers.\n\nA lot have been cleared out already, but the Highland raptors to the north have been growing in number. That won't be true for long, now will it?\n\nClear out a good deal of Highland raptors, and I'll have a nice reward for you.", sourceObjective = "Kill 8 Highland Raptors of any kind.", completion = "A job well done. Consider this reward not from me, but from Ironforge; the preservation of Khaz Modan is a matter that concerns every dwarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25865] = { id = 25865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosshide Job", description = "You seem trustworthy enough to help me out with my real problem, {name}. I was sent here by Ironforge to recover a shipment of gold ingots.\n\nThe ingots are part of the Ironforge Royal Treasury, stamped with the royal seal... only an idiot would steal them for profit, far too easy to trace. Oddly enough, this area is full of idiots: Mosshide gnolls.\n\nI don't know how many gnolls you've fought before, but they're foul and brutal beasts, and dangerous. I need you to slay them and recover the missing ingots.", sourceObjective = "Recover 8 Ironforge Ingots from Mosshide Gnolls.", progress = "There should be about eight ingots stolen.", completion = "Well done! The Ironforge Guard appreciates this, {name}. You've done our city a fine favor.\n\nBut something new has come up...", sourceObjectiveStatus = "unverified-source-field" }
quests[25866] = { id = 25866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Trappers", description = "You may have seen them while you were out, but the Dark Iron clan has been spotted in this area. They're never up to any good, and it looks like they're kidnapping the Mosshide gnolls for some reason.\n\nI don't know what their game is, but we're putting a stop to this before more foul play occurs. Go and stop them.\n\nAnd if you're worried about fairness, try askin' them politely first and see how far that gets you.", sourceObjective = "Kill 10 Dark Iron Trappers.", completion = "I don't suppose they agreed to come along quietly? Didn't think so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25867] = { id = 25867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnoll Escape", description = "I know we were just attacking the gnolls ourselves, but I'm not about to let the Dark Iron capture them as slaves. For one, we found the thieves and took back what was missing, so justice is served; for another, whatever work the Dark Iron will be putting them to isn't something I want to allow.\n\nEither way, the gnolls need to be freed. The trappers should have keys on them, so use those to open the cages.", sourceObjective = "Obtain Trapper's Keys from Dark Iron Trappers and use them to free 6 Gnolls from the Gnoll Cages.", completion = "That should do it! The more gnolls those fools have to chase after, the easier it'll be to keep them in line.", sourceObjectiveStatus = "unverified-source-field" }
quests[25868] = { id = 25868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorla Darksnare", description = "I've found out who's pulling the strings on this operation here. Yorla Darksnare is directing the Dark Iron dwarves from a camp to the east, and it might've been orders to have the gnolls steal Ironforge's gold in the first place.\n\nWhat's more, she's a wanted criminal... she's been inciting rebellion and attacks against Ironforge since Magni was still alive.\n\nShe can't slip through our fingers this time, {name}. Go and get her!", sourceObjective = "Slay Yorla Darksnare.", completion = "A job well done! You've brought one of Ironforge's most wanted to justice today, {name}. I'd say you've earned a mighty fine reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[25869] = { id = 25869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem in the Post", description = "The journey ahead must begin with you killing the Grimtotem invaders at Freewind Post. If you can't stop them here, we won't be able to move into their territory.", sourceObjective = "Slay 10 Grimtotem Invaders.", completion = "Grim business, that.<Quentin coughs.>\n\nNo pun intended.", sourceObjectiveStatus = "unverified-source-field" }
quests[25870] = { id = 25870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem in the Post", description = "You must do away with the Grimtotem invaders at Freewind Post. They brought it on themselves, the cowards!\n\nWe can't take the fight to their territory with our back to them. Please help us take back our home, {class}.", sourceObjective = "Slay 10 Grimtotem Invaders.", completion = "It's a good start. Normally, I wouldn't wish harm on any of the Earth Mother's creatures.\n\nBut attacking us at our most vulnerable moment?! They deserve to die!", sourceObjectiveStatus = "unverified-source-field" }
quests[25871] = { id = 25871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Sentinel", description = "<Brienna waves a note around with Taur-ahe markings on it.>\n\nThose monsters have captured one of our sentinels! They're threatening to kill her if we don't pull back!\n\nWe don't negotiate with cowardly beasts! Please, if you can, rescue her before it's too late, {class}.", sourceObjective = "Rescue the Feralas Sentinel.", completion = "Thank you for freeing her, {name}. Those Grimtotem monsters would have killed her in cold blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25872] = { id = 25872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brave and the Bold", description = "<Rau dismissively waves a note around with Taur-ahe markings on it.>\n\nThose mongrels have captured one of our braves! They're threatening to kill him if we don't pull back!\n\nWe'll never allow those Grimtotem cowards to keep Freewind Post! Please, rescue him before it's too late, {class}.", sourceObjective = "Rescue the Freewind Brave.", progress = "Where's our brave? Is he alive?", completion = "Thank you for freeing him, {name}. Those Grimtotem would have killed him in cold blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25873] = { id = 25873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", sourceObjective = "Collect Longhorn's Horn.", progress = "What's this, {class}?", completion = "A traitor amongst the tauren?\n\nI've never heard of such a thing. Clan rivalries and warfare are one thing, but killing your own in cold blood.\n\n<Quentin shakes his head in disbelief.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25874] = { id = 25874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", sourceObjective = "Collect Longhorn's Horn.", progress = "{name}? What news do you have?", completion = "The cliffwatcher was a Grimtotem spy?! No wonder we had no warning!\n\n<Thalia seethes with barely contained rage.>\n\nI don't want that damned thing. Throw it into the water and let the Longhorn name never be spoken again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25875] = { id = 25875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnome on the Inside", description = "Mirkfallon Lake is crawling with Horde. The goblins have set up shop and they aren't going to leave until all the oil under Stonetalon is sucked dry.\n\nThankfully I have a gnome on the inside that's been collecting information for us. If anyone knows what's going on with that bomb, it's my inside gnome.\n\nMake your way to the Sludgewerks, north of here, and find Minx. She'll be disguised as a \"goblin\" pump controller.", sourceObjective = "Seek out Minx who is disguised as a \"Goblin\" Pump Controller at the Sludgewerks in Stonetalon Mountains.", completion = "Get in here and hug a wall! I can't risk blowing my cover!", sourceObjectiveStatus = "unverified-source-field" }
quests[25876] = { id = 25876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Up There!", description = "Listen, I've been tracking this bomb since you rescued me in Ashenvale. Whatever they're doing with it is going to happen real soon.\n\nAt the top of the large oil rig is a control room. Inside that control room you'll find a Krom'gar log book. That log book is the key to where this bomb is heading. Get up there and get the log book! Bring it back here and I'll decipher it for you.", sourceObjective = "Steal the Krom'gar Log Book.", progress = "Did you recover the log book?", completion = "OH NO! They plan to \"test\" the bomb at Thal'darah Grove! That's the school for young druids located in the heart of Battlescar Valley. You've got to return to Barus with this information! Master Thal'darah must be warned!", sourceObjectiveStatus = "unverified-source-field" }
quests[25877] = { id = 25877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time for Goodbyes!", description = "RUN! Get out of here, {name}. Get back to Barus and inform him of what you've discovered. He'll arrange for you to get safely across Battlescar Valley to Thal'darah Overlook.\n\nIt's not too late to save those young druids!", sourceObjective = "Return to Scout Commander Barus at Mirkfallon Post in Stonetalon Mountains.", completion = "Blasted Horde! I've got friends at that grove. Hopefully you know how to ride a hippogryph. We've got to get you to Master Thal'darah at the overlook immediately!", sourceObjectiveStatus = "unverified-source-field" }
quests[25878] = { id = 25878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schemin' That Sabotage", description = "Goblins... What would this world be without goblins? I'll tell you what: CLEAN!\n\nThose filthy little scum suckers have planted their oil pumps all over the lake with the hope of extracting every last drop of oil that exists in Stonetalon. At each oil pump they've stationed an oil pump controller whose sole job it is to watch the pump and make sure nothing goes wrong.\n\nSomething is about to go wrong.\n\nTake out the goblin pump controllers and take their pump controls. Use 'em to overload the pumps!", sourceObjective = "Use the Goblin Pump Controller to destroy 4 Goblin Oil Pumps.", completion = "I could see the explosions from here, {name}! The Horde won't be refueling from Mirkfallon anymore, thanks to you!", sourceObjectiveStatus = "unverified-source-field" }
quests[25879] = { id = 25879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lumbering Oaf Problem", description = "Ever seen a hobgoblin? They're another vile goblin creation. Take a goblin, make it even uglier, fatter, bigger and stupider and you have a hobgoblin. Add to all of that a nasty mean streak and we've got a problem.\n\nThese lumbering oafs wander the Sludgewerks and Mirkfallon Lake, acting as muscle to the goblins.\n\nGet out there and thin 'em out. Permanently.", sourceObjective = "Kill 10 Lumbering Oafs.", completion = "Slowly, but surely, we pick away at the Horde's numbers. They won't have a leg to stand on when this war really opens up.", sourceObjectiveStatus = "unverified-source-field" }
quests[25880] = { id = 25880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Master Thal'darah", description = "There are dozens of students at Thal'darah Grove. Most of them have no means of defending themselves, ripe for the slaughter.\n\nYou must get word to Master Thal'darah of the Horde's plans. He will direct you in what you must do next.\n\nFiora Moonsoar has granted you the use of her fastest hippogryph. Take it now to Thal'darah Overlook! Don't look back, {name}! The Horde must be stopped!", sourceObjective = "Report to Master Thal'darah at Thal'darah Overlook in Stonetalon Mountains.", completion = "These are dire times, indeed, {name}. Our outpost in Stonetalon Peak has been overrun by fiendish creatures from the depths and the Horde seeks to destroy us. We need a hero, {name}; a soldier of the Alliance strong enough to guide us through these trying times.", sourceObjectiveStatus = "unverified-source-field" }
quests[25881] = { id = 25881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Wardens", description = "We held out as long as we could, {class}. But the flames... the heat... We lost the whole town.\n\nCaptain Irontree refused to pull back when the flames engulfed us. Our forces are scattered. Maybe some of the others survived? We can mount a counter-attack!\n\nGo into the Scorched Plain and rescue any lost wardens that got separated from the group. Then find Captain Irontree - he's probably taken up a fortified position in the middle of the fighting.", sourceObjective = "Locate and rescue 8 Lost Wardens.", completion = "You've assembled the survivors? Good, good. And the rest of the mountain - healed?\n\nHaha, strike me down! We're on the front lines again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25882] = { id = 25882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hand at the Ranch", description = "Captain Tharran asked me to pass along his thanks for your help and congratulations on a successful mission. He and his men are cleaning up the last of the trolls and tending to the wounded.\n\nHe also wanted me to ask you to check out reports about troll raids on the Amberstill Ranch to the north. Ask for Sergeant Flinthammer when you arrive.", sourceObjective = "Speak with Sergeant Flinthammer at Amberstill Ranch.", completion = "So you're the one who's been helping Captain Tharran beat back the Frostmane trolls? I've seen your name in the reports. It's good to finally meet you. You might be just the {class} we need to help secure the ranch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25883] = { id = 25883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Disarming", description = "Naga weapons...\n\nAs you cast your vision on the naga Holding Pens, you see dozens of similar stacks of tridents positioned strategically.\n\nDestroying their weapons could only hamper whatever wicked designs they are carrying out in this region...", sourceObjective = "You must destroy 6 sets of Naga Tridents.", progress = "Have you destroyed the naga arsenal?", completion = "You're confident that your assault on the naga armaments has made an impact on their effectiveness.", sourceObjectiveStatus = "unverified-source-field" }
quests[25884] = { id = 25884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Hell or High Water", description = "Oh fer the love of...\n\nI know our survivor friend here means well, but the lad's been severely traumatized.\n\nThere only be one way ta deal with these accursed beasts, an' that be a fine dwarven axe buried hilt-deep in the noggin.\n\nPile up enough o' their corpses an' they'll think twice before fiddlin' with yer tasty bits.\n\nMark me words <laddie/lassie>, them buggers don't like the sight o' their own blood any more than you or I.\n\nNow git out there an' give 'em what fer!", sourceObjective = "Kill 12 Zin'jatar Naga at The Clutch in Kelp'thar Forest.", completion = "The waters surrounding the Holding Pens are red with the blood of the naga.\n\nRendel would be proud!", sourceObjectiveStatus = "unverified-source-field" }
quests[25885] = { id = 25885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", sourceObjective = "Collect 7 Wiggleweed Sprouts from Shimmerspine Harvesters in The Clutch.", progress = "Were you able to find me any of their seaweed, {class}?", completion = "Yes, yes. This is the stuff.\n\nMaybe I can gradually eat less of it and avoid that side-effect.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25886] = { id = 25886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressing the Advantage", description = "It looks like most of the Twilight's Hammer has fallen back to regroup for another assault. Their most dedicated are staying behind to hold the line. This is our chance to whittle away at their leadership.\n\nRange out along the Scorched Plain and crush the Twilight Field Captains. We'll remove them from the equation!", sourceObjective = "Slay 4 Twilight Field Captains.", progress = "You've given our forces a second wind, {name}. How goes the fight?", completion = "Terrific! Twilight's Hammer will no doubt try to re-take the mountain, but they'll have to do so without the leadership of those fat-for-brains thugs.", sourceObjectiveStatus = "unverified-source-field" }
quests[25887] = { id = 25887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake of Destruction", description = "Our time here draws to a close. I must somehow follow the trail of these naga captives if we are to discover their purposes in this region.\n\nBut before I move on, I would see the destruction of this operation!\n\nNevermind their numbers, I have a plan that has the potential to even the odds.\n\nOutside this cave, famished great sharks, displaced by these naga, seek food.\n\nIn their weakened state, they will be susceptible to suggestion. Use this orb to subdue them, then direct them against our enemy.", sourceObjective = "Use the Orb of Suggestion to subdue a Famished Great Shark, then use it to destroy 12 Zin'jatar at The Clutch.", progress = "With the naga numbers dramatically lessened, we shall be able to finish our destruction of this stronghold.", completion = "It is as it should be.\n\nNow the way is clear to deal these naga a crippling blow.", sourceObjectiveStatus = "unverified-source-field" }
quests[25888] = { id = 25888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decompression", description = "I simply cannot bear the thought of so many others like this soldier imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use  it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", sourceObjective = "Use Moanah's Breathstone on 10 Imprisoned Soldiers in The Clutch.", completion = "Let us hope for the safety of those released prisoners.\n\nIn return for your noble efforts, please accept this gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[25889] = { id = 25889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Children!", description = "My poor, defenseless young students are stranded at Thal'darah Grove. With the battle raging across Battlescar Valley, they have no means of escaping. We must save the children before the Horde drops their bomb!\n\nTake my hippogryph and use it to rescue the young druids of Thal'darah Grove. Drop them off at the hippogryph post here in town.\n\nSave them all, {name}! You truly are our only hope.", sourceObjective = "Use Master Thal'darah's Hippogryph to rescue 5 Helpless Young Druids from Thal'darah Grove.", progress = "Use the whistle to call for my hippogryph, {name}.", completion = "Praise you, {name}. The hero we have been searching for has finally arrived, and not a moment too soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[25890] = { id = 25890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nespirah", description = "It is clear to me at this point what must be done, {name}.\n\nThe naga can only be obtaining these pearls from one place: Nespirah, the ancient, shelled creature that rests outside of this cave.  Why Nespirah would submit to the naga, however, is beyond my understanding.\n\nWe can enter Nespirah's body cavity through a small tube near the exit to this cave.  I must first fetch my master, then we can meet you on the inside.  We will convene in Nespirah's northwestern entrance.", sourceObjective = "Enter Nespirah's northwestern entrance, then find a way to communicate with it.", completion = "Erunak trusts this task to me?  Very well, let's see what we can learn from the ancient one.", sourceObjectiveStatus = "unverified-source-field" }
quests[25891] = { id = 25891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Ditch Effort", description = "The Horde have signaled a retreat. Look now, they fall back from the field of battle - portends of disaster.\n\nWe must make one final descent into Thal'darah Grove. I could not live with myself if any of our young druids were left behind.\n\nAssist me, hero. I will take the reins. You search for any druids that might be left behind.\n\nWe will go when you are ready.", sourceObjective = "Assist Master Thal'darah in search of any druids left behind at Thal'darah Grove.", completion = "Do you know why the Horde destroys? The Horde destroys because they cannot comprehend beauty. They fear it and that which they fear they must destroy. Why else would they destroy Thal'darah Grove?\n\nTogether, we will make them understand. They will know that what they do comes at a great cost.", sourceObjectiveStatus = "unverified-source-field" }
quests[25892] = { id = 25892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", sourceObjective = "Use Wavespeaker Valoren's sea horse to return to Admiral Dvorek under the southern terrace in the Ruins of Vashj'ir.", completion = "You made it! After the attack at the forward post, I thought we might be the only ones left. I'm very glad to see you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25893] = { id = 25893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Plan", description = "Jorlan and Hexascrub left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", sourceObjective = "Meet with Engineer Hexascrub on Biel'aran Ridge.", completion = "Impeccable timing. Like clockwork! Trouble comes. You come. Save the day.  Clockwork!\n\nWe've devised our brilliant plan. Gloriously simple, barring the hostility of local life. Simpler yet with a you available!", sourceObjectiveStatus = "unverified-source-field" }
quests[25894] = { id = 25894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Waters", description = "Hexascrub came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those gill goblins. Or at the very least, enough of them to make them a bit more wary of us.", sourceObjective = "Kill 10 Muckskin Scroungers.", progress = "These scroungers seem intensely curious about our equipment. Sometimes suicidally so. I wonder what attracts them to it so much.", completion = "Less gill goblins is good!\n\nI'm glad that they're so primitive. I don't think I'd want to be dealing with a race of aquatic tech-freaks right now. Not at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[25895] = { id = 25895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Prepared", description = "We must always come prepared. Prepared with gear. Prepared with plans. Prepared with gear plans!\n\nAll of the ships in all of the Alliance fleets stow a survival kit. A lot of our tools came from a survival kit. My balloon came from a survival kit too! But now it's gone. I need another survival kit!\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us!", sourceObjective = "Retrieve an Alliance Survival Kit.", progress = "A whole big box of amazing! That's what it is. I need more amazing in my life.\n\nDon't worry, I'll share.", completion = "Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory.", sourceObjectiveStatus = "unverified-source-field" }
quests[25896] = { id = 25896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devout Assembly", description = "Ah, Battlemaiden. You carry with you the word and the will of our Lady. I might ask a favor of you...\n\nI need Fathom-Caller Azrajar and my Tide Priestesses to return so that we can begin the ritual. Can you carry my will to them as such? You should find them spread upon the temple terrace. Azrajar will be at the stairs to the north.", sourceObjective = "Seek out Fathom-Caller Azrajar midway down the northern stairs and 6 Sira'kess Tide Priestesses on the upper portion of the ruins, and instruct them to return to the temple.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "The threat may not be sure, but the Kvaldir are certainly not fools. They would not return if they did not have some confidence in victory.\n\nThe sooner our allies are summoned, the better. Find my Tide Priestesses.", completion = "The Kvaldir have proved a greater threat than we anticipated, but our plans are not hindered in the least. As our allies arrive, we will have a force more than sufficient to usurp the Tidehunter.\n\nAll that remains is to ensure that the ritual of summoning is completed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25897] = { id = 25897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! No sense at all.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. Absolutely must.", sourceObjective = "Collect 8 Coils of Kvaldir Rope.", progress = "The rope ties the whole plan together!", completion = "This is great! I love it. It should work per... ewww! Is this stuff braided with hair?\n\nDoesn't matter. Almost done. This thing will be ready in the twist of a rope.", sourceObjectiveStatus = "unverified-source-field" }
quests[25898] = { id = 25898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Fortuitous.\n\nJorlan already swam up to catch it. Swam up and stopped to wait for it. He said you'd get the honors though. Jorlan's nice like that.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Alliance ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", sourceObjective = "Swim to the surface, retrieve the flare gun, and fire a rescue flare towards the Alliance Ships.", progress = "Those aren't trade ships, those are war ships. Still, this is an incredible stroke of luck. Fire that flare off and pray that they see it.", completion = "Perfect! There's no way they missed that, fighting or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[25899] = { id = 25899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakthrough", description = "The fiery army that caused so much devastation up the hill has retreated east of here. Only the Scorchlords remain in action. If we can punch a hole through their lines to regroup with Captain Irontree's forces, the whole offensive may collapse.\n\n{class}, I'm in no shape to continue fighting, but you look like you can do some damage. Slay those Scorchlords and regroup with Captain Irontree!", sourceObjective = "Slay 10 Twilight Scorchlords.", completion = "You killed how many? Well, well. Quite a show. I guess my men don't have any more excuses.", sourceObjectiveStatus = "unverified-source-field" }
quests[25900] = { id = 25900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Contact", description = "I can't believe that Nespirah would willingly allow these naga to take residence inside her shell.  As I see it, one of two things has happened: they have convinced her to willingly join their cause, or they have weakened her to a point where she cannot fight back.  Either one is bad.\n\nHere in this chamber, I should be able to communicate directly with Nespirah.  Let us find out for ourselves.  Speak to me when you are prepared, {class}.", sourceObjective = "Observe as Earthmender Duarn attempts to communicate with Nespirah.", progress = "Nespirah needs our help.  If nothing else, I can sense that.", completion = "That didn't go well.  For some reason, the beast won't speak back to me.\n\n<Duarn is clearly frustrated.>\n\nIf only Erunak had not left us!  He would know what to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[25901] = { id = 25901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyjal Recycling Program", description = "Reinforcements! I thought we were going to fight this out to the bitter end.\n\nVery few of the Guardians of Hyjal remain, and our supplies are running out. The battlefield around our holdout here must be littered with serviceable arrows.\n\nI know it's beneath your abilities, but can you gather up our spent ammunition? It's the only way we can replenish our supplies!", sourceObjective = "Gather 15 Warden's Arrows.", progress = "Warden's arrows are crafted of living oak, blessed in the moonwells, and tipped with obsidian arrowheads scrawled with runes invoking the blessings of nature.\n\nThey're not cheap.", completion = "Wonderful! Still sharp. A little blood on the fletching, but they'll fly true.\n\nThank you, {name}. Our defense of Hyjal can continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[25904] = { id = 25904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer and the Key", description = "My Nemesis. Still lives.\nThe servants of fire still come.\nWe must pursue. Into their den.\n\nThe ogres know the way.\nSlay the Field Captains.\nRecover the Glyph of Opening.\n\nThis is the way.", sourceObjective = "Kill a Twilight Field Captain and recover the Glyph of Opening.", progress = "The glyph. Show it to me.", completion = "This power is ancient.\nPrimitive.\nEasy.\n\nWe will use it against them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25905] = { id = 25905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rams on the Lam", description = "The rams we raise and train here at Amberstill ranch have long been the mounts of choice for Dun Morogh's mountaineers. Aye, there're a few here, but not enough to guard my family and all the animals.\n\nA few brave Frostmane raiders have taken to stealing our rams under the cover of night, taking them south into the Tundrid Hills. Would you be willing to help return them? You'll need to get fairly close to them and give a sharp whistle to get their attention. Their training will take over from there.", sourceObjective = "Recover 6 Stolen Rams from the Tundrid Hills by using /whistle.", completion = "The rams you rescued have made their way back into the pen. I've got members of the family on a day and night watch now. Those trolls won't take us by surprise again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25906] = { id = 25906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Flamegate", description = "Memorize the glyph.\nTake it within yourself.\n\nDraw it on the ground before the flamegate.\nEast of here.\nEnter the Firelands.\n\nI cannot come with you.\nBut my children await. Inside.\n\nFind Garunda Mountainpeak within the realm of flame.", sourceObjective = "Travel through the flamegate in the Scorched Plain and locate Garunda Mountainpeak within.", completion = "You were sent by the turtle god? Bless his almighty shell! I thought I was trapped down here forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[25907] = { id = 25907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slave Labor", description = "It will take me some time to break through this barrier and communicate with Nespirah.  In the meantime, you can save some of those men that the naga have enslaved in the pits below.\n\n<Duarn produces a length of rope from within his robes.>\n\nThis should come in handy.", sourceObjective = "Use Duarn's Rope to save 8 Enslaved Pearl Miners.", completion = "Excellent work, {name}... although I'm afraid I haven't been nearly as productive as you have.", sourceObjectiveStatus = "unverified-source-field" }
quests[25908] = { id = 25908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stick it to Them", description = "I may be unable to communicate directly with the beast Nespirah, but I can still feel some things indirectly.  For example, I can clearly sense that Nespirah is not happy about the naga's presence here.\n\nWhen we first entered Nespirah's body, I saw dozens of sentinels and enchantresses patrolling the central chamber floor.  Perhaps some of the ancient one's pain will be alleviated if you remove them.", sourceObjective = "Kill 7 Idra'kess Sentinels and 7 Idra'kess Enchantresses.", progress = "<Duarn is too focused on his task to notice your presence.>", completion = "Can you sense it?  If you have an ounce of shaman's blood in you, you must feel the sense of relief in the air.\n\nNespirah is pleased.  Perhaps she will finally speak with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[25909] = { id = 25909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", sourceObjective = "Use Duarn's Net to capture a Deepseeker Crab inside of Nespirah.", progress = "I hope this works.  My skills as a shaman are limited, and I fear that this task may be too much for us.", completion = "<Duarn looks at the crab and disguises a frown.>\n\nIt doesn't look very impressive, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25910] = { id = 25910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Time for Mercy has Passed", description = "This cavern is an abomination, {name}. And it's filled with horrors from the depths.\n\nI don't want any of these - things - getting through the portal to the outside world. Slay everything!", sourceObjective = "Slay 10 Molten Tormentors and 4 Shadowflame Masters.", completion = "So it is done.\n\nKnowing that Twilight's Hammer is in league with creatures of malice such as these... it really curdles the blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[25911] = { id = 25911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}.", sourceObjective = "Return to Captain Taylor at the Tranquil Wash.", completion = "That is the best news I've heard in what seems like an eternity. We'll get the survivors moving over there to the surface as soon as possible. Perhaps we can forget that this whole nightmare ever happened.\n\nThank you, {name}. I'm not sure there's anything I can do to repay you for everything you've managed to accomplish in this ocean, but I will try to find a way.\n\nYou should consider meeting us at the ships later, when you finish saying your goodbyes to the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25912] = { id = 25912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seen Better Days", description = "The world is unraveling around us, {name}. Old enemies seek to destroy us from one end, while ancient forces close in on the other.\n\n<Elder Sareth'na sighs.>\n\nI have seen better days - brighter days, and I long for them...\n\nAcross Stonetalon Peak lies the ruins of our old outpost - now overrun with darkness. If you happen to go that way, could you search for my sketch book? It holds many happy memories. I would reward you well for its return.", sourceObjective = "Find Elder Sareth'na's Sketch Book.", progress = "Have you found my sketch book?", completion = "You've found it! Elune bless you, child! Perhaps this book will give me the strength to carry on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25913] = { id = 25913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Them to Rest", description = "As the Horde were marching upon Stonetalon, I noticed that some of the sentinels had fallen ill. Not long after, they started acting strangely. When the first tentacle burst from the ground the ill sentinels began attacking us. We lost the outpost shortly after...\n\nThe sentinels in the peak are now nothing more than shells - husks for something far more sinister. I want you to put the sentinels to rest and retrieve their glaives. Each glaive returned can identify a fallen sister.", sourceObjective = "Recover 8 Sentinel's Glaives.", progress = "Recover the sentinel's glaives, {name}. Each glaive is unique to a sentinel.", completion = "Thank you, {name}. Each glaive has the name of the sentinel it belonged to imprinted upon its blade. We can now send word to their families and put their souls to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25914] = { id = 25914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Depths!", description = "Tendrils are bursting forth from the earth and terrorizing Stonetalon Peak. My sentinels are hardly making a dent in their numbers.\n\nI suspect that there is a force at the heart of Stonetalon Peak that controls the tendrils. Perhaps if we can put a stop to that force, the tendrils will return to the depths from whence they came!", sourceObjective = "Kill Harbinger Aph'lass and 10 Invading Tentacles.", completion = "I'm afraid that the death of Harbinger Aph'lass has not ceased the tendril attacks. You've done all that you can, {name}, and for that I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25915] = { id = 25915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of Tortolla", description = "The dark usurper Nemesis fled here when the fires of Hyjal receded. We are not yet strong enough to defeat Nemesis, {name}, but we may be able to turn his own strength against him.\n\nI will send a child of Tortolla with you, one of the children you freed earlier from the Twilight's corruption.\n\nSearch the depths of this cave for a Nemesis Crystal, and allow the young turtle to examine it.\n\nSee me if you lose your companion!", sourceObjective = "Escort a Child of Tortolla to a Nemesis Crystal. See Garunda Mountainpeak if you lose your companion.", progress = "What has the little one learned, {name}?", completion = "Ah yes, yes... the secret strength of Nemesis, unearthed here in these caverns.\n\nWe know all that we need to know, {name}. It is time to finish this.", sourceObjectiveStatus = "unverified-source-field" }
quests[25916] = { id = 25916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", sourceObjective = "Observe as Earthmender Duarn attempts to speak with Nespirah.", progress = "The ritual is not yet complete, {name}.", completion = "I had assumed that the naga were only here for those pearls.  No, this makes much more sense.  If they had Nespirah's power under their control, the amount of damage the naga could do would be catastrophic!\n\nSomething must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25917] = { id = 25917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Alliance slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", sourceObjective = "Find the Alliance survivors inside of Nespirah in Vashj'ir.", completion = "{name}... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[25918] = { id = 25918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", sourceObjective = "Obtain 4 Purloined Polearms from the weapon racks inside of Nespirah.", progress = "In my youth, I was given some training on spearfighting.\n\n\"Stick them with the pointy end,\" I think it was.", completion = "<Admiral Dvorek admires the polearms you present him.>\n\nOh, I'm sorry.  I was just imagining what these will look like with little bits of naga stuck to the ends of them.  Thank you, {name}.  We'll put these to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[25919] = { id = 25919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body Blows", description = "<Captain Taylor listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", sourceObjective = "Attack 7 Nespirah Abscesses along the walls of Nespirah's body chamber.", completion = "Hopefully we made some progress.  I'm not sure how we'll know when the creature wakes up, but something tells me that it will be pretty obvious when it does.", sourceObjectiveStatus = "unverified-source-field" }
quests[25920] = { id = 25920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", sourceObjective = "Obtain 5 Mysterious Pearls from Idra'kess Warlords and Idra'kess Prophets inside of Nespirah.", progress = "The naga must have some ulterior motive with these pearls.  If I had time to study them, I'm certain I could figure it out.", completion = "Brilliant work!\n\n<Valoren tucks the pearls away beneath her armor.>\n\nNow I just need you and Captain Taylor to get me safely out of here.  I can handle the studies from there on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25921] = { id = 25921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall to the southeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.", sourceObjective = "Head to the top of Nespirah and slay Overseer Idra'kess.", completion = "No need to bring me up to speed... Nespirah has been narrating your adventures as they happened, and Captain Taylor filled me in on the rest.\n\n<Duarn closes his eyes and nods.>\n\nNespirah says that she is quite grateful, and that she has a small surprise ready for the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25922] = { id = 25922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Beast", description = "Thanks to you and the Captain, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", sourceObjective = "Speak with Earthmender Duarn inside of Nespirah to activate her bio-defenses, then escape from Nespirah's body.", completion = "It appears that I owe you my life, yet again.  Thank the Light that you found me before you and your shaman activated those bio-defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[25923] = { id = 25923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish Nemesis", description = "Your turtle companion can use this newfound power to render the two of you invulnerable for a short period of time. You can \"turtle up\" to avoid the worst of Nemesis and his fury. To do so, simply invoke this totem.\n\nThis is all I can do for you. Together, you and a Child of Tortolla must defeat Nemesis, once and for all. Finish the Usurper!\n\nReturn to me if you lose your turtle friend.", sourceObjective = "Use the Totem of Tortolla and the help of a Child of Tortolla to defeat Nemesis. See Garunda Mountainpeak if you lose your turtle companion.", progress = "Is Nemesis dead?", completion = "The usurper has perished!\n\nTwilight's Hammer dreamed of creating their own pantheon of twisted ancients to rule over the land, sea, and air. With your help, they've all been executed.\n\nWe must tell Tortolla at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[25924] = { id = 25924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Duty", description = "Listen up, {race}!\n\nA new landmass has emerged off the coast of Eastern Kingdoms and we are engaged in a critical battle for control of the island!\n\nVictory there will leave Stormwind completely defenseless!\n\nNow is the time to strike!\n\nReport to the docks at once for transport to the battle.\n\nEvery warship is engaged, so you'll be boarding a mercenary vessel commissioned by the Warchief himself.", sourceObjective = "Ride the mercenary ship to battle.", completion = "Not exactly the battle you had anticipated, I'll wager. But a battle nonetheless, as you shall soon see....", sourceObjectiveStatus = "unverified-source-field" }
quests[25925] = { id = 25925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'darah's Vengeance", description = "We must attempt to establish communication with Farwatcher Glen, to the south. Our Darnassian glaive throwers are at your disposal, {name}. Use them to cut a swath through the encroaching Horde forces and clear a path to Farwatcher Glen.\n\nI only hope we're not too late to save the Glen. Should Farwatcher Glen be intact, find Hierophant Malyk and inform him of our status.", sourceObjective = "Kill 20 Horde soldiers and destroy 3 Krom'gar Demolishers in Battlescar Valley.", completion = "We witnessed the detonation of the bomb. Terrible, terrible destruction... Farwatcher Glen, for better or for worse, is still intact. Unfortunately we've nowhere to run.", sourceObjectiveStatus = "unverified-source-field" }
quests[25926] = { id = 25926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mired in Hatred", description = "The mirebeasts to the west are not my brethren... they are symptoms of the earth's disturbance, a foulness of rot given form.\n\nYou would not understand... they take the shape of my kind, infested within with decaying spores, forcing out flourished life in the swamp. They take all and leave only rot. Nothing left, nothing left!\n\nSoothe my mind, {race}. Slay the mirebeasts, cleanse the land, and perhaps my mind will settle.", sourceObjective = "Kill 10 Mouldering Mirebeasts.", completion = "Ahhh... yes. The swamp suffers less now.\n\nMore threats, though. More lurk. I can see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[25927] = { id = 25927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Threat of Flame", description = "Flame has threatened me for far too long... far too long... but it is no longer the little ones, no longer mere gnats...\n\nThe fields burn! The hills and highlands scream, {race}, they scream. The elementals brought here consume all life in their wake.\n\nThey cannot stand, they cannot stand. Stop them. STOP THEM! Destroy the bringers of flame...", sourceObjective = "Kill 8 Rampant Fire Elementals.", completion = "Yes... the flames die. There is peace now. Peace for the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[25928] = { id = 25928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortolla's Triumph", description = "I'll escort the children of Tortolla out of here and seal up this accursed portal.\n\nI'll leave it to you to inform Tortolla of our victory. Simply step back through the flamegate. The ancient will be pleased!", sourceObjective = "Step back through the flamegate and return to Tortolla at the Scorched Plain in Hyjal.", completion = "You've been to the firelands?\n\nNemesis is dead?\n\nSo it is finished.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25929] = { id = 25929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Legs", description = "Greetings, {class}. I am Erunak, a fellow survivor of this savagery.\n\nI'm afraid your travails have only just begun. The naga have been scouring these waters, attacking anyone that still lives.\n\nYou are not yet equipped to survive here, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help you grow accustomed to your environment.", sourceObjective = "Collect 3 Saltwater Starfish and a Conch Shell from the Sea Floor at Legion's Fate.", progress = "Were you able to gather the items I requested, {race}?", completion = "Here you are, {class}. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25930] = { id = 25930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascending the Vale", description = "I am told that before the great upheaval the Charred Vale was a valley, closed off to the sea. One has merely to look to the south to see that the Charred Vale is no longer a valley and in fact has become an area of great volcanic activity.\n\nSalsbury here has configured a device that will allow us to ascend the volcano. Use it to get to the top and assess the goings on.\n\nI will keep in touch with this Gnomecorder device, which Salsbury has so kindly gifted upon me.", sourceObjective = "Use Salsbury's Rocket Pack to ascend the Charred Vale's volcano.", completion = "<The Gnomecorder crackles with energy.>\n\nI say, are you there, {name}? It would appear that you are in the center of a dragon's lair.", sourceObjectiveStatus = "unverified-source-field" }
quests[25931] = { id = 25931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brood of Seldarria", description = "<The Gnomecorder buzzes.>\n\nBe very careful, {name}. You do not want to rouse that black dragon.\n\nNow, look around you. If this is a nest then there must be black dragon eggs nearby. Search the premises for eggs and destroy any that you see.\n\nReturn to me should you find and destroy Seldarria's eggs.\n\nGoldrinn watch over you.", sourceObjective = "Destroy 5 of Seldarria's Eggs.", completion = "A smashing success! Perhaps only a minor victory against the brood of Deathwing, but a victory nonetheless!", sourceObjectiveStatus = "unverified-source-field" }
quests[25932] = { id = 25932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Raid Night Every Night", description = "The reports I'm sending Captain Tharran can't really convey the amount of trouble the Frostmanes have created for us. Your assault on the village has started to relieve some of the pressure. The raids are still frequent, but the trolls don't have the numbers they once did.\n\nEven so, my men are tired and their morale is flagging. Would you help us keep watch for the Frostmane raiders? They could turn up at any time.", sourceObjective = "Help Sergeant Flinthammer and his mountaineers defend Amberstill Ranch from Frostmane Raiders.", progress = "We're glad to have your help, {name}.", completion = "With your help, we've managed to weaken the raiders considerably. They haven't suffered such losses since the raids began. Now is the time to press our advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[25933] = { id = 25933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for the Quarry", description = "Thank you again for all your help here, {name}.\n\nI have a cousin who used to work in the mines beneath the Gol'Bolar Quarry, but he hasn't been able to work since troggs flooded into the mines and took control. The quarry and its camp are just to the southeast of the ranch. Would you be willing to check in with the foreman there and see if there's anything to be done?", sourceObjective = "Speak to Foreman Stonebrow at the Gol'Bolar Quarry.", completion = "Sergeant Flinthammer? I'm not familiar with the name, but, aye, there is a Flinthammer among the miners. He's one of the ones lucky enough to make it out of the mine, but most of my men are still trapped down there.", sourceObjectiveStatus = "unverified-source-field" }
quests[25934] = { id = 25934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World First: Gnomegen", description = "Good day, citizen, allow me to introduce myself. I am Salsbury, soon to be the world's first gnomegen. Malyk has assured me that as soon as my work here is complete he will grant me the gift of the worgen.\n\nSo with the introduction out of the way, I've a request!\n\nWithin the Charred Vale, south of here, roam newly created fire elementals. I desperately need a rare blazing heart of fire from one of the fiends. Get it for me and you bring me one step closer to becoming a gnomegen!", sourceObjective = "Collect 1 Blazing Heart of Fire.", progress = "Have you recovered the blazing heart of fire?", completion = "Excellent. This will allow me to finish my last task and hopefully gain the form of the wolf!\n\n<Salsbury howls.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25935] = { id = 25935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Pups", description = "Ah, a new arrival! Good that you're here <lad/lass>! The pups are hungry and we're completely out of food.\n\nThankfully they love dragon meat, which fortuitously exists in abundance within the Charred Vale, south of here.\n\nBe a good <boy/girl> and fetch me several pounds of black dragon whelp filet.", sourceObjective = "Collect 6 Black Dragon Whelp Filets.", progress = "Hurry, {name}, the pups are hungry!", completion = "Excellent. The dogs will be well fed and ready to defend our outpost for weeks!", sourceObjectiveStatus = "unverified-source-field" }
quests[25936] = { id = 25936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", sourceObjective = "Use the Enchanted Conch to rescue 6 Drowning Warriors.", progress = "Were you able to rescue the warriors, {race}?\n\nWe will perish without their help...", completion = "While you were away, I was able to revive some of the fallen warriors.\n\nWe'll need every hand if we are to survive here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25937] = { id = 25937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priceless Treasures", description = "Mining wasn't the only thing going on in the quarry, you know. I led a team of Explorers' League excavators recovering priceless ancient artifacts.\n\nI managed to escape, but my colleagues were much deeper in the mine and didn't survive the initial trogg attack.\n\nThey took great pride in their work and they risked their lives to learn more of our history. If you're going into the mines, take this pick with you and see if you can find anything in the digs the prospectors started.", sourceObjective = "Recover 8 Frozen Artifacts from inside the Gol'Bolar Quarry Mine.", progress = "Were you able to find any artifacts down there?", completion = "Thank you for recovering these artifacts. I will see to it that they are displayed in the Ironforge museum along with the story of those who died to recover them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25938] = { id = 25938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Desolace", description = "I've received a disturbing message from Nijel's Point in Desolace. It would seem as if the great upheaval has created some new problems for them, which they are ill-equipped to handle. I was given no further information.\n\nReport to Office Jankie in Desolace. She will direct you to Nijel's Point.\n\nGood luck, {name}.", sourceObjective = "Report to Officer Jankie at Tethris Aran in Desolace.", completion = "Hold there, stranger!", sourceObjectiveStatus = "unverified-source-field" }
quests[25939] = { id = 25939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Peat's Sake", description = "The elementals rampaging across Direforge Hill are setting the very land beneath them ablaze. In a marsh such as this, fire can find many places to smoulder through the deep moss and peat.\n\nYou must quench the fires before they spread further. Take this flower... blessed by nature's rain, it will let you douse the fires.\n\nThe blossom may also prove useful against the elementals themselves.", sourceObjective = "Use the Blessed Floodlily to extinguish 7 Marsh Fires.", progress = "It is vital you extinguish as many fires as you can, {name}.", completion = "In sparing the land further suffering, you've also helped us soothe the greenwarden.\n\nMany thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25940] = { id = 25940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand at Whistling Grove", description = "We might have a chance to beat these flames back thanks to your work in the Inferno.\n\nStill, more wildlife is threatened. Keeper Taldros ran north through the flames, to Whistling Grove.\n\nSee if you can help him!", sourceObjective = "Report to Keeper Taldros at Whistling Grove in Mount Hyjal.", completion = "The forest is being devoured!", sourceObjectiveStatus = "unverified-source-field" }
quests[25941] = { id = 25941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", sourceObjective = "Speak to Legionnaire Nazgrim.", completion = "I hear you, {race}.\n\nI understand the urgency, but these men are in no condition to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25942] = { id = 25942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy Us Some Time", description = "Many good warriors have been lost today.\n\nIf what the shaman says is true, then we must act swiftly or we will add to their numbers.\n\nThe naga are out there, scouring these waters looking for survivors.\n\nWe are not yet ready to fight, {race}. You must buy us time to make preparations.\n\nFind the naga that hunt us and delay their efforts.", sourceObjective = "Kill 8 Zin'jatar Raiders at Legion's Fate.", progress = "You give those scaly scum something to think about, {race}?", completion = "Let us hope that your work has bought us the time we need...", sourceObjectiveStatus = "unverified-source-field" }
quests[25943] = { id = 25943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these orcs ready for battle.\n\nAny worthy leader knows that his warriors travel and fight on their stomachs. No food, no victory.\n\nThese warriors are weary from their struggle out there. They need food before they're ready to overcome a naga attack.\n\nSpeaking of traveling on stomachs, I saw plenty of crabs out on the sea floor...", sourceObjective = "Collect 8 Succulent Crab Meat from Splitclaw Skitterers.", progress = "You got food for the troops, {race}?", completion = "Good grub.\n\nSoon we'll be back to fighting strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[25944] = { id = 25944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Girding Our Loins", description = "As we struggled not to drown, my orcs and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I believe him.\n\nIf we're going to be victorious, we'll need your help to recover our lost equipment.\n\nYou should find it scattered around the sea floor near our shipwrecks here and to the north.\n\nMake haste, {race}. The enemy could arrive at any moment.", sourceObjective = "Collect 5 Orgrimmar Axes, 5 Orgrimmar Breastplates and 5 Orgrimmar Helms from the sea floor and from Gilblin Plunderers in Legion's Fate.", progress = "Were you able to gather up our gear, {race}?", completion = "You have done well, {race}.\n\nOur chances of survival are increasing.", sourceObjectiveStatus = "unverified-source-field" }
quests[25945] = { id = 25945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Here to Do One Thing, Maybe Two...", description = "You're in Hellscream's army now, {name}, and in Hellscream's army we kick butt and take names. Gone are the days of our people starving in the streets of Orgrimmar as we sign treaties with elves. We take what we need now. Kalimdor belongs to the Horde!\n\nThe Alliance attempts to stop our expansion every chance they get. Unsatisfied with owning most of the Eastern Kingdoms, those pig-lickers want it all!\n\nOverlord Krom'gar has called for more troops in Stonetalon. Get on the caravan west of here and go!", sourceObjective = "Take the Krom'gar Wagon to the Fold in Stonetalon Mountains.", completion = "While you remain in Stonetalon and fight as a Krom'gar soldier you will remain suited up! Am I clear? DO you hear me, grunt? If I see you without Hellscream's beloved tabard I will put my foot so far up your backside that you'll be spitting up laces.", sourceObjectiveStatus = "unverified-source-field" }
quests[25946] = { id = 25946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helm's Deep", description = "This helm and its associated components are marked with the seal of Stormwind. It was no doubt cast off from an Alliance ship that suffered a similar fate to yours.\n\nLooking closer, this seems far too intricate and sturdy to be everyday diving equipment. Perhaps Nazgrim can make some sense of this...", sourceObjective = "Take the Alliance S.E.A.L. Equipment to Legionnaire Nazgrim at The Immortal Coil.\n\nProvided item:", completion = "Blood and Thunder!\n\nThis changes everything, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25947] = { id = 25947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finders, Keepers", description = "I recognize this helm, {race}. You were wise to bring it to me.\n\nThe Alliance have a special unit, trained and equipped to explore and fight beneath the sea.\n\nIt would seem that they are in this region to do more than just defend against our attack.\n\nThere must be more of these down here, and if you can find them it could turn things around for the Vanguard.", sourceObjective = "Gather 5 pieces of Stormwind S.E.A.L. Equipment.", progress = "Were you able to locate more of the Alliance gear, {name}?", completion = "Well done!\n\nNow, more than ever, we are prepared to face the naga!", sourceObjectiveStatus = "unverified-source-field" }
quests[25948] = { id = 25948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring It On!", description = "It is time, {class}.\n\nWe are as ready as we ever will be!\n\nI shall address the Vanguard, and then we shall swim into the sea to meet our fate.", sourceObjective = "Speak with Legionnaire Nazgrim aboard the Immortal Coil.", completion = "No time to address the Vanguard.\n\nJust as well...", sourceObjectiveStatus = "unverified-source-field" }
quests[25949] = { id = 25949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood and Thunder!", description = "The time has come to make our stand, {race}.\n\nWe'll defend this ship to our last breath, and make these naga scum think twice before approaching it again!\n\nFor the Horde!", sourceObjective = "Assist Legionnaire Nazgrim in the defense of The Immortal Coil.", completion = "The Earthen Ring has received my distress message and sent help - just in time it would seem.\n\nHopefully more can be sent soon. We are but few against a great many.", sourceObjectiveStatus = "unverified-source-field" }
quests[25950] = { id = 25950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sira'kess Slaying", description = "You're the {name} everyone's been talking about? Good to meet ya, love. Let's have a butcher's hook.\n\nWell, enough rabbit, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and read and write them snakes something quick.\n\nNothing fancy. They're looking for a bother, and we'll give 'em a right good one in the ol' boat race.", sourceObjective = "Slay 10 Sira'kess Naga.", completion = "Chicken and rice, {name}! That will show those sorry and sad snakes who's the ol' pitch and toss!\n\nNow it's bird lime for that tiddlywink. Finger and thumb or plink plonk?", sourceObjectiveStatus = "unverified-source-field" }
quests[25951] = { id = 25951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Judgment", description = "Get to the bridge on the east, quickly. Lady Naz'jar and the Fathom-Lord should be there with whatever forces remain.\n\nFollow our Lady's direction, as always. Hold the bridge until we can complete the ritual.\n\nOnce our allies arrive, the Kvaldir will be doomed.", sourceObjective = "Hold the bridge on Quel'Dormir Terrace until Lady Sira'kess' allies arrive.\n\nThis task is part of a Naz'jar Battlemaiden vision. If needed, use the Blade of the Naz'jar Battlemaiden at a time focus to return to the vision.", progress = "Stand with us, Battlemaiden. We shall not fall this day.", completion = "I could ask for no more proficient a Battlemaiden than you. You have done yourself a great honor this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[25952] = { id = 25952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", sourceObjective = "Kill 10 Azsh'ir Patrollers.", completion = "Excellent work, {class}.\n\nI will get some patrols out of our own to make sure that no more naga get within sight of this cave. We should have the area secured within the hour.", sourceObjectiveStatus = "unverified-source-field" }
quests[25953] = { id = 25953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", sourceObjective = "Destroy 8 Azsh'ir Monitors.", completion = "Well done, {name}, and just in time too. The Captain just started sending more men out. Strong axe arms, but I doubt they possess quite the same awareness and finesse that you do.\n\nWe were lucky to have you here when things went south. I suspect you will have a large role to play in things to come as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[25954] = { id = 25954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance.", sourceObjective = "Investigate the 4 intact statues in the Vashj'ir Gardens.", completion = "Thank you so much for taking this seriously.\n\nThis is some of the first definitive proof of other members of the Vashj family. Very interesting. And I'd never even heard of either of the other two figures you mentioned until now.\n\nSo much of our history was lost during the sundering - it's exciting to have a chance at reclaiming some of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25955] = { id = 25955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", sourceObjective = "On the lowest level of the ruins, scout the northern end of the Quel'Dormir Gardens, the passage that leads under the ruins west of the gardens, and the structures at the southeast corner of the ruins, below the bridges.", completion = "This is good intel. You have a sharp eye, {class}.\n\nIt sounds like the building north of the gardens will make a suitable forward post. I will send some men immediately to start defensive preparations and we will reposition there as soon as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[25956] = { id = 25956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", sourceObjective = "Bring the broken shard back to the Legion's Rest.", progress = "Yes, {class}?", completion = "A shard of metal?\n\nThe remains you describe sound much like the sea vrykul we encountered in Northrend. We'll not be striking any alliances with their sort, no matter the cause. Still, this information may prove useful in the future.\n\nI will think on it further if time permits. Thank you for bringing it to my attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[25957] = { id = 25957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", sourceObjective = "Use the Blade of the Naz'jar Battlemaiden at the battle site at the southeast end of the ruins.", completion = "A Battlemaiden? I never heard of such a thing.\n\nThe way you explain it, it sounds like the naga forces are far greater in scope than the Captain could possibly have realized. We might be able to learn more through the blade if we can find other locations where this Battlemaiden was present, but the information you gave me makes me fear for the captain and his soldiers. We must warn them.", sourceObjectiveStatus = "unverified-source-field" }
quests[25958] = { id = 25958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Forward", description = "The Captain used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", sourceObjective = "Find and speak to Captain Vilethorn north of the Quel'Dormir Gardens.\n\nUse Wavespeaker Tulra's sea horse to reach the forward post quickly.", completion = "Good to see you again, {class}. I almost thought we'd lost you to the Wavespeaker's fool errand.\n\nDid anything come of it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25959] = { id = 25959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south, under the far terrace?", sourceObjective = "Kill 10 of the naga forces building up on the ground level, under the southwestern terrace.", completion = "More naga are amassing to the south than reported too it seems. We shall have to move quickly then.", sourceObjectiveStatus = "unverified-source-field" }
quests[25960] = { id = 25960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Entirely Unprepared", description = "I overheard your conversation with the Captain. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Bring them more crossbow bolts to buy us some extra time.", sourceObjective = "Deliver 8 Bundles of Crossbow Bolts to Horde Lookouts on ledges around the north end of Quel'Dormir Gardens.", progress = "Finished already?", completion = "You are perhaps the most dependable {race} I've ever met. I wish I could have more men that showed half as much pride as you do.", sourceObjectiveStatus = "unverified-source-field" }
quests[25962] = { id = 25962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Properly Inspired", description = "Been all over the place. Blown all kinds of things up. I thought I might have some trouble carrying on the trend, what with the water and all, but it's all just a matter of inspiration.\n\nI found something volatile enough to make bombs out of! There's a bunch of kelp hanging under the terrace to the southwest. Normally kelp stores gas that makes it float - this kelp produces a different kind of heavy gas. It keeps it hanging, but also makes for great explosions.\n\nGather me some?", sourceObjective = "Gather 8 Bloated Kelp Bulbs hanging under the southwestern terrace.", progress = "Tick, tock, tick, tock. Always in such a hurry. No time for innovation. What I wouldn't give for a lab again!", completion = "You are brave indeed! I've seen you battling all manner of murloc, naga, and pointy-toothed fish, but that was nothing! The way you just sling those kelp bulbs under your arm like that is a whole new kind of fearless. BOOM! You could blow up at any second.\n\nYou're my kind of {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25963] = { id = 25963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the run. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the southern terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", sourceObjective = "Speak to Fiasco Sizzlegrin just outside of the building to join the assault, then use your improvised explosives to kill 100 Azsh'ir Soldiers, 20 Azsh'ir Wave Screamers, and 12 Azsh'ir Archaens.", completion = "You did great up there, soldier! You devastated their ranks, but there were far more than we accounted for, and most of my men went down out there in the masses of naga.\n\nWe'll need to hold this position as long as possible to buy them time. Hopefully some of them will still make it to the rendezvous.", sourceObjectiveStatus = "unverified-source-field" }
quests[25964] = { id = 25964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", sourceObjective = "Rescue 6 Injured Assault Volunteers.", progress = "These guys aren't in good shape. We may need to retreat sooner than we'd like.", completion = "Thank you. Truly.\n\nWe need to get these men moving as soon as possible. I'll meet you back at the forward post soon, I'm sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[25965] = { id = 25965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The captain winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", sourceObjective = "Scout the northwestern portion of the circular terrace and the tunnel under the main stairs to the north. Both locations are on Nar'shola Terrace, the middle level of the ruins.", progress = "Any word... on their numbers?", completion = "Still so many? They must want something very important here to come in such numbers.\n\nI will be honest with you, {name}, because you deserve at least that: I don't know how much hope there is. We will retreat shortly, but we won't be able to defend ourselves when they strike back. We don't have anywhere to run... we're running out of options.\n\nI'm sorry, I should keep such thoughts to myself. Do me a favor and don't mention any of that to the men. I'll figure something out.", sourceObjectiveStatus = "unverified-source-field" }
quests[25966] = { id = 25966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", sourceObjective = "Witness the continuing story of the Battlemaiden by using her broken blade at the site of the Kvaldir General's death.", completion = "You're finished! Just in time. I don't think we could have held them much longer.\n\nAn artifact? Could this be something we can use against the naga? I suppose that would require finding it.\n\nWe may have to attend to more pressing matters first, until an opportunity to pursue this further presents itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[25967] = { id = 25967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", sourceObjective = "Use Wavespeaker Tulra's sea horse to return to Captain Vilethorn just north of the Quel'Dormir Gardens.", completion = "You made it! After the attack at the forward post, I thought we might be the only ones left. It's good to see you in one piece, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25968] = { id = 25968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Plan", description = "Toldrek and Fiasco left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", sourceObjective = "Meet with Fiasco Sizzlegrin on Biel'aran Ridge.", completion = "Look at you, a regular aquatic hero! Trouble comes. You come. Save the day.  You must be proud of yourself!\n\nWe've devised our brilliant plan. Gloriously simple, barring the hostility of local life. Simpler yet with a you available!", sourceObjectiveStatus = "unverified-source-field" }
quests[25969] = { id = 25969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Waters", description = "Fiasco came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those giblins. Or at the very least, enough of them to make them fear us.", sourceObjective = "Kill 10 Muckskin Scroungers.", progress = "These scroungers seem intensely curious about our equipment. Sometimes suicidally so. I wonder what attracts them to it so much.", completion = "Less gilblins is good.\n\nI'm glad that they're so primitive. I don't think I'd want to be dealing with a race of aquatic tech-freaks right now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25970] = { id = 25970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Prepared", description = "It's a short swim to the top. Not much trouble really. Hard to get any supplies up there though. Too heavy.\n\nAll of the ships in all of the Horde fleets stow a survival kit. I had a balloon from the old survival kit, but it fell on hard times recently. I need another survival kit.\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us.", sourceObjective = "Retrieve a Horde Survival Kit.", progress = "A whole big box of amazing! That's what it is. I need more amazing in my life.\n\nDon't worry, I'll share.", completion = "Let me see, let me see... flare gun... balloon... no rope. Never any rope. Terribly impractical if you do ask me. Rope should be mandatory.", sourceObjectiveStatus = "unverified-source-field" }
quests[25971] = { id = 25971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! Rope and bombs, that's all they should store. The rest of this stuff is just a waste of space.\n\nExcept maybe the balloon. That's coming in handy right now.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. It is non-optional.", sourceObjective = "Collect 8 Coils of Kvaldir Rope.", progress = "The rope ties the whole plan together!", completion = "This is great! I love it. It should work per... ewww! Is this stuff braided with hair?\n\nDoesn't matter. Almost done. This thing will be ready in the twist of a rope.", sourceObjectiveStatus = "unverified-source-field" }
quests[25972] = { id = 25972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Well played.\n\nToldrek already swam up to catch it, all concerned about currents and what not. He said you'd get the honors though. Nice guy - don't know how he lasts.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Horde ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", sourceObjective = "Swim to the surface, retrieve the flare gun, and fire a rescue flare towards the Horde Ships.", progress = "Those aren't trade ships, those are war ships. Still, this is an incredible stroke of luck. Fire that flare off and pray that they see it.", completion = "Perfect! There's no way they missed that, fighting or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[25973] = { id = 25973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}.", sourceObjective = "Return to Legionnaire Nazgrim at Legion's Rest.", completion = "That is the best news I've ever heard. We'll get the survivors moving over there to the surface as soon as possible. Perhaps we can forget that this whole nightmare ever happened.\n\nThank you, {name}. You've shown your worth down here. There will be a glorious spot in the Horde for you.\n\nYou should consider meeting us at the ships later, when you finish saying your goodbyes to the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25974] = { id = 25974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sira'kess Slaying", description = "So, you're the {name} everyone's been talking about? It's good to finally meet you.\n\nWell, enough talk, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and kill those naga real quick.\n\nNothing fancy. They're looking for a fight, and we'll give them one! Well, you will.", sourceObjective = "Slay 10 Sira'kess Naga.", completion = "Nice, {name}! That will show those naga who's the boss!\n\nNow it's time for that drink. You want rum or wine?", sourceObjectiveStatus = "unverified-source-field" }
quests[25975] = { id = 25975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Reclamation", description = "We've got our reinforcements, but we still need to find a way to pay them. That kind of action doesn't come cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. I think that it's time to reclaim some of it for the cause.", sourceObjective = "Collect 6 Deepfin Plunder.", progress = "How much plunder have you managed to reclaim, {name}?", completion = "That should be enough for now. We know where there's more should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[25976] = { id = 25976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Reclamation", description = "Blood and thunder! We have our reinforcements, but they still need to be paid. They won't be cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. It's time to reclaim some of it for the Horde.\n\nHellscream's eyes are upon you, {name}!", sourceObjective = "Collect 6 Deepfin Plunder.", progress = "How much plunder did you get, {name}?", completion = "That's a lot! And we know where there's more should the need arise.", sourceObjectiveStatus = "unverified-source-field" }
quests[25977] = { id = 25977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Standard Day for Azrajar", description = "{name}, the snakes are after our daft and barmy. Go back northwest to Deepfin Ridge and plant some do me good in that pot and pan pitch and toss of theirs.\n\nThey'll kick and prance away with their alderman's nails tucked between their nutmegs when they see that. Not that they've got any nutmegs mind you.", sourceObjective = "Plant the Alliance Standard in Fathom-Caller Azrajar's corpse.", completion = "Nice Uncle Bob of pokin' their general.\n\n<The lieutenant shakes her head and grins.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25978] = { id = 25978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entombed in Ice", description = "Khurgorn tells me the cataclysm upset the balance of the elements all over the world. Helm's Bed Lake, to the south, used to be beautiful and tranquil, but it is now overrun with agitated water elementals. When they started to leave the confines of the lake, I sent my troops in to keep them busy, but most have been frozen in blocks of ice.\n\nIf we can break them free, they have a good chance of recovering. I cannot spare the men for a second expedition out onto the lake. Would you be willing to try?", sourceObjective = "Break open six Icy Tombs to free the Frozen Mountaineers trapped inside at Helm's Bed Lake.", progress = "Were you able to help any of the mountaineers?", completion = "You've done it! The mountaineers are returning to camp and our medics will have their hands full. We are all in your debt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25979] = { id = 25979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with the Surge", description = "The elements are in turmoil, {class}. The cataclysm stirred up the long-dormant water spirits of Helm's Bed Lake, just to the south. They're angry, confused, and unwilling to hear my pleas.\n\nI have tried everything I know to calm them, to persuade them to stop lashing out and attacking the sergeant's mountaineers.\n\nIt pains me to say this, but no other options remain -- we must kill the elementals.", sourceObjective = "Kill 6 Helm's Bed Surgers at Helm's Bed Lake.", completion = "It is never easy to countenance violence against the very elements whose powers I wield, but sometimes there is no other solution. Our duty to the people of Dun Morogh comes first.", sourceObjectiveStatus = "unverified-source-field" }
quests[25980] = { id = 25980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Standard Day for Azrajar", description = "{name}, the naga are after our forces. I need you to go back northwest to Deepfin Ridge and stick our standard in their general, Fathom-Caller Azrajar.\n\nThey'll swim away with their tails tucked between their... er. Well, I guess they don't have any legs, now do they?", sourceObjective = "Plant the Horde Standard in Fathom-Caller Azrajar's corpse.", completion = "Stuck him right through, did you? I would have loved to have seen that!", sourceObjectiveStatus = "unverified-source-field" }
quests[25981] = { id = 25981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Aren't Masks", description = "{name}, there are these demon squid-things out there that are eating gilblins' heads and then taking them over! That's one way to get slaves.\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things?", sourceObjective = "Collect 6 Merciless Heads.", progress = "How many you got?", completion = "Ah, they're ugly, but they mostly look harmless. Smelly though.\n\nHere, let me clean the gilblin stuff out of these. I've got an idea....", sourceObjectiveStatus = "unverified-source-field" }
quests[25982] = { id = 25982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Aren't Masks", description = "{name}, there are demon squids out there that are eating gilblins' heads and then taking them over! They better not come in here!\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things? Preferably dead, I think.", sourceObjective = "Collect 6 Merciless Heads.", progress = "What's that smell?", completion = "Ah, they're ugly, but they mostly look harmless. Mostly. They're almost cute in a way.\n\nHere, let me clean the gilblin stuff out of these. I've got an idea....", sourceObjectiveStatus = "unverified-source-field" }
quests[25983] = { id = 25983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promontory Point", description = "We need to get this information up to Captain Taylor on Promontory Point! He's out there to the northwest with Erunak Stonespeaker and the Earthen Ring.", sourceObjective = "Speak with Captain Taylor on Promontory Point in Vashj'ir.", completion = "That's very disturbing news, but I believe our Earthen Ring friends here have a plan.\n\nAnd now that you're here....", sourceObjectiveStatus = "unverified-source-field" }
quests[25984] = { id = 25984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promontory Point", description = "{name}, I need you to get this information to Legionnaire Nazgrim on Promontory Point. He's up there to the northwest with Erunak Stonespeaker and those Earthen Ring people.", sourceObjective = "Speak with Legionnaire Nazgrim on Promontory Point in Vashj'ir.", completion = "If it weren't you saying it, I wouldn't believe what that troublesome goblin has to say. This is troubling indeed, but I think our Earthen Ring friends have a few ideas.\n\nAnd now that you're here....", sourceObjectiveStatus = "unverified-source-field" }
quests[25985] = { id = 25985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings Over Mount Hyjal", description = "{name}, is it true you're going to try to commune with the ancients?\n\nSouthwest of here is the Shrine of Aviana, the matron of all flying creatures. It's the home of my favorite instructor, Choluna. I've never encountered one who was so deeply in touch with the spirits of this world. You could learn a lot from her!\n\nThe recent attacks have isolated the shrine. But it's easily accessible from the air - look for the second biggest tree on Hyjal. Good luck!", sourceObjective = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "Oh, you were sent here by Tiala? A wonderful student, she'll do many great things.\n\nAlthough I sense even greater potential from you.\n\nPlease, stay a while in our shrine. There's much to do, but you can't accomplish anything with a troubled mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25986] = { id = 25986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Lake", description = "You've been a great help in securing the mines and rescuing the trapped miners.\n\nThe Senate will be heartened to hear that you and Captain Tharran's mountaineers have made progress in securing Dun Morogh.\n\nWhat worries me is that I haven't seen any reports from Sergeant Bahrum and his detachment. They were sent east, along the road toward Helm's Bed Lake, and ordered to set up a small outpost. Would you go to Bahrum's Post and check in on the sergeant?", sourceObjective = "Speak with Sergeant Bahrum at Bahrum's Post.", completion = "It's a good thing the Senator didn't come out here on his own. It's dangerous, and we're going to need all the help we can get to get the situation under control.", sourceObjectiveStatus = "unverified-source-field" }
quests[25987] = { id = 25987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put It On", description = "Hey, {name}, I've got an idea for a disguise! Take one of these merciless whatchamacallits and put it on your head.\n\nWhat could possibly go wrong?\n\nReady to put it on?", sourceObjective = "Witness what occurs when you place the Merciless One on your head.", completion = "What happened? That thing wasn't completely dead! Maybe I should stick to mechanical stuff.\n\nIt gave you a vision? Of killing all of us?! That doesn't sound good.\n\nWell, in any case, that Earthen Ring fellow, Erunak Stonespeaker, wants these specimens all taken out to him. I'll make sure he gets them. I don't want them anywhere near me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25988] = { id = 25988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put It On", description = "I've got an idea for a sweet disguise, but I'm going to need your help, {name}! Take one of these merciless corpses and put it on your head.\n\nI know, I know, but it's dead, so what could possibly go wrong other than you smelling bad for a day or two?\n\nReady to put it on?", sourceObjective = "Witness what occurs when you place the Merciless One on your head.", completion = "My bad. My name is Fiasco for a reason. I should have known that thing wasn't completely dead when it wiggled a little.\n\nYou say it gave you a vision? Of killing all of us?! That doesn't sound good.\n\nHrm, well that Earthen Ring fellow, Erunak Stonespeaker, wants these specimens all taken out to him. I'll make sure they get out there. It's not like I want them stinking up the place around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25989] = { id = 25989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", sourceObjective = "Use Duarn's Net to capture a Deepseeker Crab inside of Nespirah.", progress = "I hope this works.  My skills as a shaman are limited, and I fear that this task may be too much for us.", completion = "<Duarn looks at the crab and disguises a frown.>\n\nIt doesn't look very impressive, does it?", sourceObjectiveStatus = "unverified-source-field" }
quests[25990] = { id = 25990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", sourceObjective = "Observe as Earthmender Duarn attempts to speak with Nespirah.", progress = "The ritual is not yet complete, {name}.", completion = "I had assumed that the naga were only here for those pearls.  No, this makes much more sense.  If they had Nespirah's power under their control, the amount of damage the naga could do would be catastrophic!\n\nSomething must be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25991] = { id = 25991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Horde slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", sourceObjective = "Find the Horde survivors inside of Nespirah in Vashj'ir.", completion = "{name}... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[25992] = { id = 25992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", sourceObjective = "Obtain 4 Purloined Polearms from the weapon racks inside of Nespirah.", progress = "In my youth, I was given some training on spearfighting.\n\n\"Stick them with the pointy end,\" I think it was.", completion = "<Captain Vilethorn admires the polearms you present him.>\n\nOh, I'm sorry.  I was just imagining what these will look like with little bits of naga stuck to the ends of them.  Thank you, {name}.  We'll put these to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[25993] = { id = 25993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body Blows", description = "<Legionnaire Nazgrim listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", sourceObjective = "Attack 7 Nespirah Abscesses along the walls of Nespirah's body chamber.", progress = "You'd better keep trying, {name}.  These naga aren't going anywhere unless you wake the creature up.", completion = "Hopefully we made some progress.  I'm not sure how we'll know when the creature wakes up, but something tells me that it will be pretty obvious when it does.", sourceObjectiveStatus = "unverified-source-field" }
quests[25994] = { id = 25994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", sourceObjective = "Obtain 5 Mysterious Pearls from Idra'kess Warlords and Idra'kess Prophets inside of Nespirah.", progress = "The naga must have some ulterior motive with these pearls.  If I had time to study them, I'm certain I could figure it out.", completion = "Brilliant work!\n\n<Tulra tucks the pearls away beneath her armor.>\n\nNow I just need you and Legionnaire Nazgrim to get me safely out of here.  I can handle the studies from there on.", sourceObjectiveStatus = "unverified-source-field" }
quests[25995] = { id = 25995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall northeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.  Hellscream's eyes are upon you!", sourceObjective = "Head to the top of Nespirah and slay Overseer Idra'kess.", completion = "No need to bring me up to speed... Nespirah has been narrating your adventures as they happened, and Legionnaire Nazgrim filled me in on the rest.\n\n<Duarn closes his eyes and nods.>\n\nNespirah says that she is quite grateful, and that she has a small surprise ready for the naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25996] = { id = 25996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Beast", description = "Thanks to you and the Legionnaire, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", sourceObjective = "Speak with Earthmender Duarn inside of Nespirah to activate her bio-defenses, then escape from Nespirah's body.", completion = "It appears that I owe you my life, yet again.  Thank Hellscream that you found me before you and your shaman activated those bio-defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[25997] = { id = 25997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Scheming", description = "A cadre of Dark Iron spies have taken over Ironband's Compound to the south, beyond Helm's Bed Lake. The mountaineers are normally able to keep them from getting into Dun Morogh, but everything is in disarray right now.\n\nThe Dark Iron dwarves would be fools if they didn't take advantage of the chaos. We have to find out what they're planning and stop them before they do any damage.\n\nWill you see if you can discover what they're doing down at Ironband's Compound?", sourceObjective = "Kill 5 Dark Iron Spies and capture the Dark Iron Attack Plans from Captain Beld at Ironband's Compound.", progress = "What are the Dark Irons up to?", completion = "I knew they weren't here to see the sights.\n\n<The sergeant examines the plans you captured, his eyes wide.>\n\nThis is more serious than we thought! This is no mere raid. The Dark Irons intend to cripple the defense of Ironforge itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[25998] = { id = 25998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to the Airfield", description = "According to the plans you captured, the Dark Irons are planning a large-scale attack on the Ironforge Airfield! The council has moved most of our forces down into Dun Morogh to deal with the instability brought by the cataclysm, leaving our defenses weakened at the airfield.\n\nWe need a way to get you to the airfield quickly. Take the road back west toward Gol'Bolar Quarry and find Mathel Rustwrench. He should have a flying machine you can use. Go!", sourceObjective = "Board Mathel's Flying Machine at the Gol'Bolar Quarry.", completion = "Thank goodness you're here, {name}. The airfield's been attacked by the Dark Irons and I don't think we can hold out much longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25999] = { id = 25999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrier to Entry", description = "Filthy, good-for-nothin' night elves have managed to disarm our entire minefield in Talondeep Pass. Somebody is gonna have to go back up there and re-arm them all! A perfect task for a worthless grunt like you, {name}. Here's to hopin' you don't blow yourself up in the process.\n\nYou'll find our \"Elf Killers\" scattered across Talondeep Pass, directly north of here. Take this wrench and get to work, maggot.", sourceObjective = "Arm 8 Krom'gar \"Elf Killers.\"", progress = "What do you have to report, grunt?", completion = "<Saurboz looks you over.>\n\nYou have all of your limbs intact. This is a first.", sourceObjectiveStatus = "unverified-source-field" }
quests[26000] = { id = 26000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", sourceObjective = "Speak to Gurrok in Deepmist Grotto.", completion = "...{race}? Here?\n\nI must be mad...", sourceObjectiveStatus = "unverified-source-field" }
quests[26001] = { id = 26001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Blastgineer", description = "It looks like you might not be completely useless after all. Perhaps you can handle something a little more important.\n\nAbout two days ago I sent Blastgineer Fuzzwhistle to Windshear Mine. He was supposed to get there, make sure everything was going according to plan with the bomb, and report back. Two days and nothin'...\n\nHead out to the woods south of here and find him. For his sake, he better be dead.", sourceObjective = "Find Blastgineer Fuzzwhistle.", completion = "Blastgineer Fuzzwhistle is definitely dead. It's probably for the best.\n\nIt looks like he's holding a note in his hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[26002] = { id = 26002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Attack Plans", description = "<You pry the note loose from Fuzzwhistle's hand.>\n\nThey're onto us! They know all about the bomb. Planning an attack on Krom'gar Fortress! I think they sent a search party after me. Won't go out like a chump. They'll get a fight.\n\nI think I hear them coming now! Their leader is a high elf huntress named Davinia. She spoke of attack plans. Avenge me by killing her and getting those plans! Her tent is nearby, to the east.\n\nHellscream's eyes are upon you...", sourceObjective = "Recover the Alliance Attack Plans from Huntress Davinia.", progress = "Did you find Fuzzwhistle?", completion = "Damn shame... He was a good goblin.\n\n<Saurboz shakes his fist.>\n\nAs for you, {name}, you've done well. These attack plans will help us prepare. I want you to deliver the plans to Overlord Krom'gar personally! There's sure to be a promotion in it for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26003] = { id = 26003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons from the Lost Isles", description = "There are great dangers in the woods south of here. They are crawling with Darnassian scouts - assassins sent from Darnassus to kill us. Perhaps we can turn the tables on them, eh?\n\nWhen I was marooned on the Lost Isles a goblin gave me these infrared heat focals. They allow the wearer to see heat signatures of certain creatures. Take the focals and use them while in the woods to the south. They will allow you to easily spot the scouts. Kill as many of them as you can! For the Horde!", sourceObjective = "Kill 12 Darnassian Scouts.", completion = "Well done, brother! Now they will know that they cannot sneak up on the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26004] = { id = 26004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krom'gar Fortress", description = "Our main base of operations in Stonetalon Mountains is Krom'gar Fortress. It is from there that Overlord Krom'gar oversees all Horde military activity in the region. Krom'gar reports everything that happens directly to the Warchief.\n\nThe attack plans you brought back detail an assault that's supposed to take place against Krom'gar Fortress soon. Take the plans and head to the fortress, southwest of here. Give them to the Overlord.\n\nSo long, {name}. Truly, Hellscream's eyes are upon you.", sourceObjective = "Deliver the Alliance Attack Plans to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", progress = "What is the meaning of this interruption? Why does this grunt stand before Overlord Krom'gar?", completion = "<Overlord Krom'gar takes the plans from you.>\n\nHmm. Perhaps this grunt is more than he would appear. Perhaps this grunt is in actuality a sergeant.\n\nLook now upon Krom'gar Sergeant {name}, soldiers. He has come to serve warning of a cowardly Alliance attack. An attack that we will CRUSH!", sourceObjectiveStatus = "unverified-source-field" }
quests[26005] = { id = 26005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Breath of Fresh Air", description = "Captain Taylor and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nHexascrub left these behind for you. They should speed your trip up a bit.", sourceObjective = "Find Captain Taylor aboard Voldrin's Hold, on the surface above the Ruins of Vashj'ir.\n\nProvided item:", completion = "You made it out! Good to see you, {name}.\n\nIt's good to be out of the water for a bit, and to have some resources at our disposal again. I'm sure many of the boys would give anything to turn around and head home after what we've been through, but we still have a grim task ahead.\n\nWhat about you? Want to stick it through to the end with us? I wouldn't blame you if you've had your fill.", sourceObjectiveStatus = "unverified-source-field" }
quests[26006] = { id = 26006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Breath of Fresh Air", description = "Legionnaire Nazgrim and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nFiasco left these behind for you. They should speed your trip up a bit.", sourceObjective = "Find Legionnaire Nazgrim aboard the Stygian Bounty, on the surface above the Ruins of Vashj'ir.\n\nProvided item:", completion = "Looks like you make it out in one piece, {class}!\n\nIt's good to be out of that foul pit of water for a moment, and to have some resources at our disposal again. Don't get too comfortable though, we still have a grim task ahead.\n\nWhat about you? Had enough honor for one day, or do you want to get back in there and make Hellscream proud?", sourceObjectiveStatus = "unverified-source-field" }
quests[26007] = { id = 26007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debriefing", description = "This warrior was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", sourceObjective = "Speak with Gurrok and learn about his ordeal.", progress = "That's it, {race}.\n\nThat's all I know...", completion = "Well, it's not encouraging, but it's something...", sourceObjectiveStatus = "unverified-source-field" }
quests[26008] = { id = 26008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decompression", description = "I simply cannot bear the thought of so many others like this warrior imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use  it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", sourceObjective = "Use Moanah's Breathstone on 10 Imprisoned Warriors in The Clutch.", completion = "Let us hope for the safety of those released prisoners.\n\nIn return for your noble efforts, please accept this gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[26009] = { id = 26009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek and Destroy", description = "The Alliance encroaches upon our territories within Stonetalon. The forces of Northwatch have broken through our blockade in the south and occupy Windshear Valley, to our west. From the northern front comes an onslaught of night elf soldiers. All must be stopped!\n\nVenture forth into Stonetalon and destroy all Alliance soldiers that cross your path. Let their deaths serve as a message.\n\nStonetalon belongs to the Horde!", sourceObjective = "Slay any 20 soldiers of the Alliance in Stonetalon Mountains.", completion = "Much more blood shall be spilled upon this soil before this war is over. Alliance blood...", sourceObjectiveStatus = "unverified-source-field" }
quests[26010] = { id = 26010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "The Alliance have grown bold. Just west of here, in Windshear Valley, Northwatch troops have set up camp. No doubt they are preparing for the assault you warned us of, {name}. They will never get the chance!\n\nTake this flame thrower. It is the same flame thrower my incinerators use to burn our enemies out of hiding in the forests. Use it to destroy the Northwatch tents. Leave only ashes in your wake!", sourceObjective = "Use the Krom'gar Flamethrower to destroy 8 Northwatch Tents.", completion = "Lok'tar! Alliance pigs!\n\n<Overlord Krom'gar spits on the ground.>\n\nEnjoy the victory for it shall be short lived. Your bravery has given us more time to prepare, nothing more.", sourceObjectiveStatus = "unverified-source-field" }
quests[26011] = { id = 26011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy of the Horde: Marshal Paltrow", description = "My scouts have tracked the cause of this latest fiasco to one man: Marshal Paltrow. He commands the Northwatch forward camp that has established itself in Windshear Valley, west of here. Take him out and you remove a powerful Alliance field commander from the equation.\n\nPaltrow must die, {name}.", sourceObjective = "Kill Marshal Paltrow.", completion = "Did you find any suspicious documents at Paltrow's camp? Perhaps on his rotting corpse? Any insight into the Alliance's attack patterns would be extremely helpful in the battle for Stonetalon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26012] = { id = 26012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Wyrmrest", description = "My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple.\n\nPressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?", sourceObjective = "Speak with Krasus at Wyrmrest Temple in Dragonblight.", completion = "Thank you for heeding Rhonin's call, brave adventurer.\n\nLet me share with you what we know regarding recent events, and any assistance you might offer would be greatly appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[26013] = { id = 26013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Sanctum", description = "{race}, something terrible has transpired within the Ruby Sanctum beneath the Temple.\n\nThe entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst.\n\nEnter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.", sourceObjective = "Investigate the Ruby Sanctum beneath Wyrmrest Temple.", completion = "Thank you again, {class}, for rescuing me from Baltharus's clutches!\n\nThere is still much work to be done, however....", sourceObjectiveStatus = "unverified-source-field" }
quests[26014] = { id = 26014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Digsong", description = "Private {name}, at attention!  Ve are havink a small problem!\n\nVe have sent Humphrey and Oskar Digsong out to Underlight Canyon, to the northvest, but they are not comink back.  They vere supposed to scout out the area, but ve have lost all contact with them.\n\nYour assignment, Private {name}, is to locate our comrades and, if they live, bring them back to me!", sourceObjective = "Report to Humphrey Digsong at Underlight Canyon in Vashj'ir.", completion = "Of course we haven't returned yet!  We've had our fair share of setbacks... not the least of which was the passing of my dear brother Oskar.\n\n<Humphrey sniffles loudly.>\n\nHe lost his grip and floated away, the poor lad!  He thought he'd grab some fish to bring back to the captain, but he floated off, and was eaten by one o' those... those great-eels!  Bwaaaah ha ha haaaah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26015] = { id = 26015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phosphora Hunting", description = "Oskar's last wish, before he floated up into that great-eel's gullet, was to bring back food for the captain, so that's what we'll do.\n\nMy brother had a genius plan.  He saw those murlocs luring fish out of the reeds with a phosphorescent antenna, and devised a way to make one of his own.  All ya need is something that glows.\n\nKill the crabs and groupers that roam the canyon's floor.  They aren't edible themselves, but their phosphora is far more valuable than their meat.", sourceObjective = "Obtain 6 Underlight Phosphora from Pyreshell Scuttlers and Luxscale Groupers in Underlight Canyon.", progress = "We need enough phosphora to make a really bright light, especially if you're going to be competing with those murlocs.", completion = "<Humphrey grabs the phosphora from you and attaches it to an unusual device.>\n\nThere ya go.  It's beautiful!  Oskar would be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26016] = { id = 26016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders from Base Camp", description = "Paltrow, establish a foothold in Windshear Valley. A strong ground assault is vital to our campaign! When we make our assault against Krom'gar, your men will provide the chaos and confusion that the gnome flying machines will need to get close enough to bomb the orc fortress.\n\nThe flying machines will detonate the Krom'gar bomb while it's sitting in their base, taking out the entire fortress in the process.\n\nBurn after reading.\n\n-Force Commander Valen\n\nNorthwatch Expedition Base Camp", sourceObjective = "Deliver the Orders from Base Camp to Overlord Krom'gar at Krom'gar Fortress in Stonetalon Mountains.", progress = "More gnomes?", completion = "Gnomish flying machines? Our anti-air cannons are still not functional! We will be sitting ducks.\n\nI require time to plan... to think...\n\nThe hot air balloon and its payload cannot remain at Krom'gar Fortress. I must make arrangements to move the balloon to another location. Our plans to destroy Windshear Hold with it are foiled.", sourceObjectiveStatus = "unverified-source-field" }
quests[26017] = { id = 26017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lure", description = "Stick this device on your head, then swim through the kelp and coral along the canyon's edge.  There should be all kinds of little fish in there that find your new antenna irresistible.\n\nWhen we return to Darkbreak Cove, we'll have armfuls of fish for everyone!", sourceObjective = "Put on the Phosphora Fedora, then swim through the coral in Underlight Canyon to attract 30 Underlight Nibblers.", progress = "How many did ya catch?", completion = "Ya did good, {name}!  Ya did real good!", sourceObjectiveStatus = "unverified-source-field" }
quests[26018] = { id = 26018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldlights Out", description = "Oh yeah!  I was supposed to put together a report!  I'd almost forgotten!\n\nLooks like mostly harmless wildlife around here... 'cept for those blasted eels... and a few murlocs.  Cap'n will be more interested in the murlocs, I think.\n\nGo engage a few of 'em in combat and see what kinda moves they got.  From what I've seen, the big ones hunt for fish in the kelp, and the little ones practice some kind o' magic or another... but that's all I know.", sourceObjective = "Kill 4 Coldlight Hunters and 4 Coldlight Oracles.", completion = "<Humphrey listens as you recount your fights with the Coldlight murlocs.>\n\nHmm... they sound like regular ol' murlocs... just underwater.  That'll make Cap'n Glovaal happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[26019] = { id = 26019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enormous Eel Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Humphrey might be interested in something like this.>", sourceObjective = "Deliver the Enormous Eel Egg to Humphrey Digsong at the bottom of Underlight Canyon in Vashj'ir.", progress = "What've ya got there, {name}?", completion = "Whaaa... an egg?  An EEL egg?\n\n<Even upside-down, you can see the gears in Humphrey's head turning.>\n\nWe can definitely do something with this!  Get ready kid, 'cause it's time for some good ol'-fashioned Digsong revenge!", sourceObjectiveStatus = "unverified-source-field" }
quests[26020] = { id = 26020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Bombgutz", description = "We must prepare for the impending attack. I will have our soldiers prepare the bomb for transport. I want you to report to Chief Blastgineer Bombgutz. She has been working to fix our anti-air cannons, but has thus far failed. Make sure that she is properly motivated to repair our guns, {name}.", sourceObjective = "Report to Chief Blastgineer Bombgutz at Krom'gar Fortress in Stonetalon Mountains.", completion = "Properly motivated? Wha... what does that mean? Listen, Sergeant, I have a built in mechanism for survival called self-interest. That is, it's in my best interest to NOT DIE. With that said, there's no fixing these guns without the right materials.", sourceObjectiveStatus = "unverified-source-field" }
quests[26021] = { id = 26021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brothers Digsong 2: Eel-Egg-Trick Boogaloo", description = "Those eels ate my brother.  My brother, {name}!  It's time someone showed 'em who's boss.\n\n<Humphrey removes several sticks of dynamite from his vest and shoves them through the egg's outer membrane.>\n\nThe great-eels to the south are too tough to fight one-on-one, but with this egg, we should be able to even the odds.  Place it near one of those creatures, then... kablooie!\n\nIf the bomb doesn't kill the eel outright, it should be near enough to death for you to finish it off.", sourceObjective = "Use the Eel-splosive Device near a Devious Great-Eel in Underlight Canyon, then defeat the Weakened Great-Eel.", completion = "Oskar's alive?  Wait... what did ya say?  Ya let him FLOAT AWAY AGAIN?!\n\nWell... ya held up your end of the bargain, and I appreciate everything ya've done, {name}.\n\nHere... take this.  I've only been hanging onto it as ballast, but it doesn't seem to be doing much good.", sourceObjectiveStatus = "unverified-source-field" }
quests[26022] = { id = 26022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Blood", description = "Be prepared, {name}. You will cast the first blood upon this land for us.\n\nThe Syndicate, as they call themselves, are cowardly humans who betray even their own kind. Their isolation will make them easy prey.\n\nTravel north, slay any Syndicate members you find, and claim Northfold Manor in the name of the Forsaken. Bring me the Bloodstone Amulets they wear as proof of your conquest.", sourceObjective = "Collect 10 Bloodstone Amulets from members of the Syndicate.", progress = "I won't be swayed by empty claims. Have you proof of your loyalty?", completion = "This is but a prelude to the slaughter we will visit upon these lands. All will know our name.\n\nYou have done well, {name}. Victory for Sylvanas!", sourceObjectiveStatus = "unverified-source-field" }
quests[26023] = { id = 26023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken Trollbane", description = "Let me tell you a story.\n\nOnce, there was a foolish troll named Zengu. He was tasked to find the sword Trol'kalar, the legendary blade of the human Trollbane line. He succeeded, and thinking his task done, went to leave Arathi by himself. There he was cut down by the humans, and the sword simply reclaimed.\n\nWe will not be so foolish. Our apothecaries have given us the perfect guide to reobtain Trol'kalar: the prince who once held it.\n\nHe stands ready to guide you, {name}. Speak with him.", sourceObjective = "Speak with Galen Trollbane.", completion = "Yes... I was once Prince of the fallen kingdom of Stromgarde. I was cut down by the one seeking Trol'kalar.\n\nI rue my foolish life now. I serve...only Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26024] = { id = 26024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted! Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", sourceObjective = "Bring Marez's head to Captain Nials at Refuge Pointe.", progress = "Greetings, {class}.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, {name}.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26025] = { id = 26025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor Orc", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of her energy.\n\nFind the warlock and kill her. Bring me whatever magical object you find on her person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", sourceObjective = "Retrieve Marez Cowl's Befouled Bloodstone Orb.", progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, {name}. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse.", sourceObjectiveStatus = "unverified-source-field" }
quests[26026] = { id = 26026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of a Better Tomorrow", description = "Mr. D is sick, <mister/miss>. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. D alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. D's stuff back so he can teach those baddies in the Alliance a lesson?", sourceObjective = "Recover the BD-816 War Apparatus, Mechanized Fire, Mechanized Ice and Mechanized Air.", progress = "Mr. D is so sad. We need to make him happy!", completion = "<Clarissa claps excitedly.>\n\nMr. D you're gonna be ok! Hooray!\n\n<Clarissa expertly places all of the parts you collected into Large Daddy.>\n\nOh, Mr. D! I knew it!", sourceObjectiveStatus = "unverified-source-field" }
quests[26027] = { id = 26027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms", description = "Our next strike against the ogres will bring you further east to Stromgarde. The living consider these gutted ruins worth clinging to. Their sentimentality is disgusting!\n\nAll that Stromgarde holds for us is a foul den of more ogres, waiting to be struck down. Travel there and slay their shamans and lords, and ensure what passes for leadership among the ogres is snuffed out.", sourceObjective = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords in Stromgarde.", completion = "Cleared out properly? Good. I doubt we'll even bother to lurk in Stromgarde. That ramshackle hole needs to be razed into dust.\n\nThe land would make a decent spot for a new Undercity in its place.", sourceObjectiveStatus = "unverified-source-field" }
quests[26028] = { id = 26028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. D's Wild Ride", description = "Now Mr. D just needs an angel to help him navigate. Will you be that angel, <mister/miss>? With you helping we can go out into the crag and kill bunches and bunches of Alliance! Waddya say? Come on, <mister/miss>! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Alliance Mr. Krom'gar will buy us all ice cream!", sourceObjective = "Kill 20 Gnome Engineers and 5 Gnome Pounders.", completion = "<Overlord Krom'gar coughs.>\n\nI am - perhaps for the first time in my life - at a loss for words.\n\nI am really not sure where Clarissa even came from...", sourceObjectiveStatus = "unverified-source-field" }
quests[26029] = { id = 26029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Real Threat", description = "Or'Kalar leads the ogres here. He has evaded slaughter for years. His very presence is an affront to the Dark Lady; Mug'thol, traitor to the Forsaken, commands him from afar!\n\nWe do not suffer ogres or traitors on Forsaken land. Bring me this ogre's head and I will make sure it's burned properly this time.", sourceObjective = "Slay Or'Kalar and take his head.", progress = "Speak quickly.", completion = "This is the fate of all who would stand in our way.", sourceObjectiveStatus = "unverified-source-field" }
quests[26030] = { id = 26030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Strom", description = "In ancient times, Lord Ignaeus of Strom, named Trollbane, led the first human civilization of Arathor in war against the trolls. His blade was Trol'kalar--troll slayer, in their ancient tongue.\n\nI was one of the last of his line, sworn with guarding Trol'kalar...a duty in which I failed. But now, we will obtain it once more, for my new master.\n\nThe sword is bound by three sigils. The first is held by the Syndicate traitors that lurk the ruins of Stromgarde. Slay them, and return the sigil to me.", sourceObjective = "Collect the Sigil of Strom from Syndicate members in Stromgarde Keep.", progress = "Only the Syndicate agents in Stromgarde will have the sigil. Spilling blood outside the fortress's walls will be a waste of your time.", completion = "I hated the Syndicate in life as much as I do in death. To see the sigil again is a small comfort.\n\nBut we have much more work to do... for Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[26031] = { id = 26031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Thoradin", description = "In life, I divided the sigil of Thoradin into five pieces to protect it, spreading it among my most loyal men. This too failed, but my successor will have done the same.\n\nThe defenders of Stromgarde hold the pieces of the sigil yet again. Slay them, and bring the shards to me; I will reassemble them.", sourceObjective = "Collect 5 Sigil Fragments from Stromgarde defenders in Stromgarde Keep.", progress = "All five pieces are needed to restore the sigil...", completion = "Thoradin was the founder of Arathor. Just as I join these fragments together, he joined the scattered tribes of humans into their first great nation.\n\nBut I'm sure you're not interested in such drivel. Forgive me. Old memories are often hard to bury.", sourceObjectiveStatus = "unverified-source-field" }
quests[26032] = { id = 26032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Arathor", description = "I entrusted the sigil of Arathor to Lieutenant Valorcall, leader of my cavalry. He barely escaped with his life when it was taken.\n\nIt is unlikely he will do so again. Valorcall patrols the road between Stromgarde Keep and Refuge Point. Find him, and take the sigil from him once more.", sourceObjective = "Collect the Sigil of Arathor from Lieutenant Valorcall.", progress = "Have you the sigil?", completion = "Valorcall was loyal to me in life. His death will not be something I bear lightly.\n\nBut bear it I must. I am Forsaken. My old existence means nothing.\n\nThe sigils are ours; Trol'kalar awaits.", sourceObjectiveStatus = "unverified-source-field" }
quests[26033] = { id = 26033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trol'kalar", description = "The last sigil is mine...and with it, the four combine to the Sigil of Trollbane, key to the tomb. We are ready.\n\nTrol'kalar lies sealed with its master's remains, within Trollbane's tomb in the catacombs of Stromgarde. It will be defended heavily...but my presence before you is proof enough that the defenders can be overcome.\n\nEnter the tomb, retrieve Trol'kalar, and bring it here.", sourceObjective = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde Keep.", progress = "Have you Trol'kalar?", completion = "Trol'kalar, my father's blade... it seems like it's been an eternity since I saw it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26034] = { id = 26034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Destroyer", description = "This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.\n\nZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen.\n\nSlay him, {name}, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.", sourceObjective = "Defeat Halion and repel the invasion of the Ruby Sanctum.", completion = "<Krasus listens intently as you relate your battle with Halion, and then his eyes go wide at the mention of Deathwing.>\n\nWe owe you a debt of gratitude, mortal, for driving the invaders from the Sanctum. But this news of the Destroyer is troubling beyond words. I have much to discuss with the other members of the Accord.\n\nTake these as a token of my thanks, as you gird yourselves for the coming storm.", sourceObjectiveStatus = "unverified-source-field" }
quests[26035] = { id = 26035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worth Its Weight in Gold", description = "Archmage Malin sent me here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need Witherbark tusks and Witherbark medicine pouches.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", sourceObjective = "Collect 10 Witherbark Tusks and 4 Witherbark Medicine Pouches from Witherbark Trolls.", progress = "Have you had any luck so far?", completion = "Not bad. Since it's clear you've got your head on straight, I was hoping you could help us with a more pressing job.", sourceObjectiveStatus = "unverified-source-field" }
quests[26036] = { id = 26036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wand over Fist", description = "Hey, {name}. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", sourceObjective = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", progress = "Our goal is the wand, {name}. Focus on that for now.", completion = "Brilliant, {name}. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26037] = { id = 26037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to ward you against the tower's defenses. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant it.", sourceObjective = "Find an Azure Agate and bring it to Apprentice Kryten at Stromgarde Keep.", progress = "{name}, hello again. Have you found an azure agate yet?", completion = "You amaze me, {name}. Well done again.\n\nGive me a moment to cast the proper spell an' you'll be ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[26038] = { id = 26038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on the Tower", description = "Here's what you're looking for: Trelane's phylactery, Trelane's orb, and Trelane's ember agate.\n\nAll three should be in chests within the tower.  You shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nYou'll need to have your weapons at the ready. Those ogres find out you're there and stealing from them, and they'll be sure to put the hurt on you.\n\nBe careful, and good luck.", sourceObjective = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, {name}. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been.", sourceObjectiveStatus = "unverified-source-field" }
quests[26039] = { id = 26039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, {name}, aid me!", sourceObjective = "Gather 12 Motes of Myzrael from Drywhisker Kobolds.", progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free...", sourceObjectiveStatus = "unverified-source-field" }
quests[26040] = { id = 26040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", sourceObjective = "Collect 7 Wiggleweed Sprouts from Shimmerspine Harvesters in The Clutch.", progress = "Were you able to find me any of their seaweed, {race}?", completion = "Yes, yes. This is the stuff.\n\nMaybe I can wean off of it and avoid the side-effect.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26041] = { id = 26041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", sourceObjective = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.", progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "<Myzrael speaks through the stone.>\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble {class}, {name}.  My rescuer!", sourceObjectiveStatus = "unverified-source-field" }
quests[26042] = { id = 26042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n{name}, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", sourceObjective = "Obtain the Rod of Order from Fozruk.", progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you...", sourceObjectiveStatus = "unverified-source-field" }
quests[26043] = { id = 26043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BEWARE OF CRAGJAW!", description = "By order of Overlord Krom'gar, Cragpool Lake is OFF LIMITS!\n\nThe ferocious beast known as Cragjaw has made the lake a death trap. Should you dispatch of Cragjaw, take his huge tooth as a trophy and return it to Spy-Mistress Anara for a reward.", sourceObjective = "Kill Cragjaw and take Cragjaw's Huge Tooth.", progress = "What is it that you require?", completion = "A testament to the might of the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26044] = { id = 26044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are the Parts?", description = "I've been waiting on parts for these guns for days! I sent one of my best blastgineers and two dozen miners into the Deep Reaches five days ago for the parts. After not hearing from anybody for three days I began to get a little worried. The Overlord sent two of his best orcs in to see what was going on. We've received no reports since then...\n\nHead into the Deep Reaches, directly below this fortress, and find out what's going on! I need parts!", sourceObjective = "Speak to Sergeant Dontrag inside the Deep Reaches in Stonetalon Mountains.", completion = "Um... Well you see, it's quite simple... THIS CAVE IS SWARMING WITH SOULLESS KILLING MACHINES!", sourceObjectiveStatus = "unverified-source-field" }
quests[26045] = { id = 26045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Got Your Parts Right Here...", description = "Here's the dilemma: I could do one of two things, get killed down here like everyone else or get killed up at Krom'gar Fortress when Krom'gar realizes we've lost the mine. I'm choosing the third option, do nothing. So far, so good.\n\nYou need parts? Plenty from the left over junk scattered about in this mine. You just gotta go get 'em.\n\nGood luck! Maybe if you get those parts we might be able to show our faces at Krom'gar Fortress.", sourceObjective = "Collect 10 Spare Parts.", progress = "How's that part hunt going?", completion = "I'll be damned! You managed to get the parts and not die. How are you only a sergeant?", sourceObjectiveStatus = "unverified-source-field" }
quests[26046] = { id = 26046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between a Rock and a Hard Place", description = "Dontrag can explain it better than me. Basically, we're stuck between a rock and a hard place. Can't do anything down here due to all of the things that can kill us and can't go back to the base due to all of the things that can kill us - you know?\n\nPerhaps if we worked together we might be able to get this mess sorted out. How about you get started by clearing out some of these elementals that have apparently killed everything in the mine, ok?", sourceObjective = "Kill 12 Raging Earth Elementals.", completion = "Get the parts, kill the elementals and rescue the peons... We get all of that done and we're as good as promoted!", sourceObjectiveStatus = "unverified-source-field" }
quests[26047] = { id = 26047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And That's Why They Call Them Peons...", description = "These two are USELESS! When they first arrived I thought we were saved. Not so! Instead, Dontrag and Utvoch took one look at the mine and concocted some idiotic plan that involved standing here until... until we all died, I guess. \n\nYou don't look nearly as useless. How about you lend a hand, friend? I've got dozens of peons, scared out of their gourds, hiding in the Deep Reaches. Find them and get them out!", sourceObjective = "Rescue 10 Frightened Peons.", progress = "Did you find my peons?", completion = "I knew it! You are a hero! If I have anything to do with it, you'll be promoted to legionnaire!", sourceObjectiveStatus = "unverified-source-field" }
quests[26048] = { id = 26048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts Up In Here!", description = "Whew, that was tough. I didn't think we'd make it, {name}. We better get these parts back to Chief Blastgineer Bombgutz. I think I hear the gnome flying machines buzzing outside. We haven't got a minute to lose!", sourceObjective = "Deliver the Crate of Spare Parts to Chief Blastgineer Bombgutz at Krom'gar Fortress in Stonetalon Mountains.", progress = "Get my parts?", completion = "Just in time! The flying machines are starting to mass. Attack is imminent!", sourceObjectiveStatus = "unverified-source-field" }
quests[26049] = { id = 26049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Unleashed", description = "Myzrael's no innocent princess. She's a terribly dangerous force, and the giants had every reason to chain her down there. I'm afraid you've been had.\n\nAccording to Gerrig, you have to summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards.\n\nHere's the scroll you'll need. Be careful with it; I risked a few teeth to get it. Good luck, {name}.", sourceObjective = "Summon and defeat Myzrael at the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", sourceObjectiveStatus = "unverified-source-field" }
quests[26050] = { id = 26050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goggle Boggle", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", sourceObjective = "Escort Professor Phizzlethorpe to the cave and back.", progress = "This is no time to talk! The goggles need to be charged with the power of the stone!", completion = "The goggles work perfectly now! Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26051] = { id = 26051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, {name}, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", sourceObjective = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, {name}! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!", sourceObjectiveStatus = "unverified-source-field" }
quests[26052] = { id = 26052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Shakes", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, {name}, take these to O'Breen.", sourceObjective = "Take the Elven Gems to Captain O'Breen at Faldir's Cove in Arathi Highlands.", progress = "Ahoy, {class}.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!", sourceObjectiveStatus = "unverified-source-field" }
quests[26053] = { id = 26053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Highlands", description = "No threat here will go overlooked. If we are to secure these lands under the Dark Lady's rule, we will tear from them everything living, inch by inch, piece by piece.\n\nTo the northeast, not a stone's throw away from this camp is an ogre mound. The Boulderfist ogres that dwell in it must be eradicated, {class}.\n\nThey are in the way. Show no mercy or hesitation.", sourceObjective = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers.", completion = "Excellent. The march of the Forsaken continues.", sourceObjectiveStatus = "unverified-source-field" }
quests[26054] = { id = 26054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water They Up To?", description = "Sandfury trolls working with the Twilight's Hammer?!\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", sourceObjective = "Slay Kai'ju Gahz'rilla and inform General Marcus Jonathan in Stormwind City.", sourceObjectiveStatus = "unverified-source-field" }
quests[26055] = { id = 26055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", sourceObjective = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", progress = "Bah, maybe I should go kill those naga scum myself.  It's obvious you're not goin' to do it.\n\nMaybe I can find some knitting needles so you can keep yourself busy.", completion = "Nice work out there, {name}.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace.", sourceObjectiveStatus = "unverified-source-field" }
quests[26056] = { id = 26056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", sourceObjective = "Find Wavespeaker Valoren in the Nightmare Depths of Vashj'ir.", completion = "I sure am glad you're here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26057] = { id = 26057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", sourceObjective = "Find Wavespeaker Valoren in the Nightmare Depths of Vashj'ir.", completion = "I sure am glad you're here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26058] = { id = 26058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Krom'gar Fortress", description = "There's no time left. Here they come! Take control of a heavy gun and shoot the gnomes out of the sky! If that bomb takes too many hits it will blow, taking us all with it!\n\nDefend the base, {name}! You're our only hope!\n\nIf we somehow make it out of this in one piece, report to Overlord Krom'gar.", sourceObjective = "Destroy 15 Gnomish Flying Machines or Bombers and 25 Gnome Wing Commanders.", progress = "Our enemies surround us!", completion = "I have never seen such an act of bravery. You saved the base, sergeant - or should I say legionnaire! Lok'tar!", sourceObjectiveStatus = "unverified-source-field" }
quests[26059] = { id = 26059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes and Ears: Malaka'jin", description = "Honor's Stand has been lost. The Horde's grip on the Barrens shattered along with the land itself. I now receive reports that we are at risk of losing Malaka'jin to a concerted attack by the Alliance and the Grimtotem. If Malaka'jin falls, half of Stonetalon falls with it!\n\nYou have proven yourself a capable soldier of the Horde. Will you be my eyes and ears at Malaka'jin? Witch Doctor Jin'Zil awaits your arrival.\n\nMalaka'jin is located far to the south.", sourceObjective = "Report to Witch Doctor Jin'Zil at Malaka'jin in Stonetalon Mountains.", completion = "I see that Krom'gar has sent his best!\n\nGood, we have much work to do. The filth that is the Alliance have entered into a treaty with the Grimtotem. Now we fend off attacks from both forces.\n\nWe are spread thin across the Greatwood Vale and will soon fall beneath the concerted effort of our enemies. There is only one hope: VOODOO!", sourceObjectiveStatus = "unverified-source-field" }
quests[26060] = { id = 26060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo: Stormer Heart", description = "With voodoo, our troops might have a chance at beating back the Grimtotem assault. With that said, I need several ingredients if I am to invoke black magic.\n\nThe first ingredient on my list is a heart from a cliff stormer. The beasts have nearly been hunted to extinction, but a few still exist around these parts. Find one and recover its beating heart!", sourceObjective = "Obtain a Cliff Stormer Heart.", progress = "I need the cliff stormer heart.", completion = "Excellent. Once I have everything I need I will mix it all together and unleash the voodoo! Woe unto our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[26061] = { id = 26061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo: Ram Horns", description = "If I am to invoke voodoo, I will need several special reagents. Bring me horns from the Stonetalon rams of the region, {name}! Without the horns we are done for!", sourceObjective = "Obtain 6 Stonetalon Ram Horns.", progress = "I need the Stonetalon ram horns!", completion = "Excellent. Once I have everything I need I will mix it all together and unleash the voodoo! Woe unto our enemies!", sourceObjectiveStatus = "unverified-source-field" }
quests[26062] = { id = 26062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo: Resonite Crystal", description = "The final ingredient for the voodoo ritual is a special type of crystal called resonite. It can only be found in the Boulderslide caverns, west of here. Beware the kobolds! They guard the resonite with their lives!", sourceObjective = "Obtain 8 Resonite Crystals.", progress = "I need the resonite crystals!", completion = "Finally! Now I will create the charm that will hold the voodoo enchantment!", sourceObjectiveStatus = "unverified-source-field" }
quests[26063] = { id = 26063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Queen and Her Court", description = "<Darn grunts.>\n\nHrmph.\n\nThings falling apart. Darn not happy. Now Darn's mate killed by spiders at Webwinder Hollow. Darn demands vengeance!\n\nHelp Darn? Kill Queen Silith and her little spiderlings? For Darn? For Darn's mate!\n\nWebwinder Hollow is northwest of here, up the path. Go!", sourceObjective = "Kill Queen Silith and any 10 spiders in Webwinder Hollow.", completion = "Darn still not very happy, but Darn will reward you for what you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[26064] = { id = 26064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight On Their Stomachs", description = "The troops are hungry, {name}. With our supply lines cut off, we're steadily running out of food. I can cook the soldiers a feast if you can get me some ingredients.\n\nHead into the woods west of here and look for Kalimdor eagle nests. Steal the eggs from the nests and bring them back to me.", sourceObjective = "Collect 8 Kalimdor Eagle Eggs.", progress = "I need eggs!", completion = "Thank you, {name}. These eggs should get us through the week.", sourceObjectiveStatus = "unverified-source-field" }
quests[26065] = { id = 26065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Wil'hai", description = "Those tentacle horrors rising from the depths have trapped that poor beast. Please, {name}, can you save it by destroying those things?\n\nWill you free Wil'hai?\n\nHere, take my totem and plant it near the tentacles. The cold it emanates will cause major shrinkage on those monsters and then you'll be able to destroy them.", sourceObjective = "Slay all of the Tentacle Horrors to free Wil'hai.", progress = "Wil'hai is still trapped.", completion = "Thank you, {name}.\n\nThese nightmarish creatures that rise from below give me pause. I fear that our efforts will be for nothing.", sourceObjectiveStatus = "unverified-source-field" }
quests[26066] = { id = 26066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements...", description = "It would appear as if we are running out of big, stupid orcs to send at the enemy. This is a problem. Thankfully, I may have a solution.\n\nTake this whip and head west to Boulderslide Cavern. Within the cave you will find a filthy nest of kobolds. Use my whip to subdue the beasts. Once subdued they will do whatever we ask them to do.\n\nReturn to me when you have amassed a sizable army of kobolds.", sourceObjective = "Use Subjugator Devo's Whip to Subdue 6 Boulderslide Kobolds.", progress = "Do not dilly-dally, {name}.", completion = "In times of crisis, a desperate act may be all that is needed to secure victory. Sending a swarm of kobolds at the enemy may be the edge that we need to win.", sourceObjectiveStatus = "unverified-source-field" }
quests[26067] = { id = 26067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'Zil's Blessing", description = "Ah, it is done! Now to test it out.\n\nTravel to the main point of conflict within Greatwood Vale and use my voodoo stick on the Krom'gar marauders battling the Grimtotem. My voodoo magic should renew their vigor and allow them to crush our enemies!\n\nGo now, {name}!", sourceObjective = "Use Jin'Zil's Voodoo Stick to infuse 12 Krom'gar Marauders with Voodoo.", progress = "Hurry, {name}!", completion = "Victory, at last! Though it stands to reason that without a stable supply line this victory will be short lived. Enjoy it while it lasts, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26068] = { id = 26068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobold Fury!", description = "We now command the kobold armies of Stonetalon! It almost sounds impressive. Almost.\n\n<Devo sighs.>\n\nThe Alliance base camp north of here is tightly guarded. It is nigh impregnable, save for the entry point by the Unearthed Grounds, northeast of here. Take this kobold war horn and head towards the Unearthed Grounds. Enter from the east, {name}! Once there, head west until you arrive at the location I have marked upon your map. Use the horn there to unleash kobold fury upon the Alliance!", sourceObjective = "Use the Kobold War Horn near the Horde Banner at the Unearthed Grounds to unleash the Kobold Army!", progress = "On my mark, unleash kobold hell!", completion = "<Devo laughs.>\n\nFascinating tale, friend. It would seem that our newfound kobold allies might be somewhat useful after all!", sourceObjectiveStatus = "unverified-source-field" }
quests[26069] = { id = 26069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nura Pathfinder", description = "Southern Barrens is under attack by the Alliance. The tauren have sent out a call for help that we simply cannot ignore. All able bodied soldiers of the Horde should assist.\n\nIf you wish to help, take the path to the High Road, located in the village. Seek out Nura Pathfinder.", sourceObjective = "Report to Nura Pathfinder on the High Road in Southern Barrens.", completion = "The situation is grim, {race}. We need all of the help that we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[26070] = { id = 26070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Defiled", description = "Our Earthen Ring friends here are wondering if we can lend them a hand. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nCan you take care of that for me?", sourceObjective = "Slay any 8 Crushing Eels, Deep Remoras, or Chasm Stalkers.", completion = "Good enough for me.\n\nDon't get too complacent, {name}. The hard part's about to come.", sourceObjectiveStatus = "unverified-source-field" }
